CREATE SEQUENCE IF NOT EXISTS phong_chieu_id_phong_chieu_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS phim_id_phim_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS the_loai_id_the_loai_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS dao_dien_id_dao_dien_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS dien_vien_id_dien_vien_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS hinh_anh_id_hinh_anh_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS trailer_id_trailer_seq START WITH 1 INCREMENT BY 1;
