CREATE SEQUENCE IF NOT EXISTS ghe_ngoi_id_ghe_ngoi_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS suat_chieu_id_suat_chieu_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS ve_phim_id_ve_phim_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS combo_an_uong_id_combo_seq START WITH 1 INCREMENT BY 1;
