CREATE SEQUENCE IF NOT EXISTS checkin_ve_id_checkin_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS otp_codes_id_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS review_images_id_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS review_replies_id_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS email_templates_id_template_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE IF NOT EXISTS email_history_id_email_seq START WITH 1 INCREMENT BY 1;
