-- ========================================
-- TẠO CÁC BẢNG
-- ========================================

-- Bảng 1: Bảng vai trò
CREATE TABLE vai_tro
(
    id_role     SERIAL PRIMARY KEY,
    ten_vai_tro VARCHAR(100) NOT NULL UNIQUE,
    trang_thai  VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG'))
);

-- Bảng 2: Bảng rạp chiếu
CREATE TABLE rap_chieu
(
    id_rap_chieu   SERIAL PRIMARY KEY,
    ten_rap_chieu  VARCHAR(100) NOT NULL UNIQUE,
    dia_chi        VARCHAR(255) NOT NULL,
    khu_vuc        VARCHAR(100),
    thanh_pho      VARCHAR(100),
    trang_thai     VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG', 'BAO_TRI')),
    so_dien_thoai  VARCHAR(10)  NOT NULL CHECK (so_dien_thoai ~ '^[0-9]{10}$'),
    mo_ta          TEXT,
    ngay_tao       TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat  TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    so_phong_chieu INTEGER     DEFAULT 0,
    tong_so_ghe    INTEGER     DEFAULT 0
);

-- Bảng 3: Bảng phòng chiếu
CREATE TABLE phong_chieu
(
    id_phong_chieu  SERIAL PRIMARY KEY,
    ten_phong_chieu VARCHAR(100)   NOT NULL,
    dien_tich_phong DECIMAL(10, 2) NOT NULL CHECK (dien_tich_phong > 0),
    trang_thai      VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG', 'BAO_TRI')),
    id_rap_chieu    INT            NOT NULL REFERENCES rap_chieu (id_rap_chieu) ON DELETE CASCADE
);

-- Bảng 4: Bảng phim
CREATE TABLE phim
(
    id_phim             SERIAL PRIMARY KEY,
    ten_phim            VARCHAR(100)   NOT NULL,
    mo_ta               TEXT,
    thoi_luong          INT            NOT NULL CHECK (thoi_luong > 0),
    ngay_phat_hanh      DATE           NOT NULL CHECK (ngay_phat_hanh <= CURRENT_DATE + INTERVAL '1 year'),
    trang_thai          VARCHAR(20)             DEFAULT 'DANG_CHIEU'
        CHECK (trang_thai IN ('DANG_CHIEU', 'SAP_CHIEU', 'NGUNG_CHIEU')),
    dinh_dang           VARCHAR(50)    NOT NULL CHECK (dinh_dang IN ('2D', '3D', '4D', 'IMAX')),
    ngay_tao            DATE           NOT NULL CHECK (ngay_tao <= CURRENT_DATE),
    tuoi_gioi_han       VARCHAR(10)    NOT NULL DEFAULT 'P'
        CHECK (tuoi_gioi_han IN ('P', 'T13', 'T16', 'T18')),
    nam_san_xuat        INTEGER        NOT NULL DEFAULT EXTRACT(YEAR FROM CURRENT_DATE),
    do_pho_bien         VARCHAR(20)             DEFAULT 'PHO_BIEN'
        CHECK (do_pho_bien IN ('PHO_BIEN', 'IT_PHO_BIEN', 'DAC_BIET')),
    gia_ve_co_ban       DECIMAL(10, 2) NOT NULL DEFAULT 50000.00,
    ngay_cap_nhat       TIMESTAMP               DEFAULT CURRENT_TIMESTAMP,
    luot_xem            INTEGER                 DEFAULT 0,
    danh_gia_trung_binh DECIMAL(3, 2)           DEFAULT 0.00,
    CONSTRAINT phim_ten_phim_nam_san_xuat_unique UNIQUE (ten_phim, nam_san_xuat)
);

-- Tạo index để tối ưu hiệu suất truy vấn
CREATE INDEX idx_phim_ten_nam ON phim (ten_phim, nam_san_xuat);

-- Bảng 5: Bảng thể loại
CREATE TABLE the_loai
(
    id_the_loai  SERIAL PRIMARY KEY,
    ten_the_loai VARCHAR(100) NOT NULL UNIQUE
);

-- Bảng 6: Bảng phim thể loại
CREATE TABLE phim_the_loai
(
    id_phim          INT REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_the_loai_phim INT REFERENCES the_loai (id_the_loai) ON DELETE CASCADE,
    PRIMARY KEY (id_phim, id_the_loai_phim)
);

CREATE INDEX idx_phim_theloai_phim ON phim_the_loai (id_phim);

-- Bảng 7: Bảng đạo diễn
CREATE TABLE dao_dien
(
    id_dao_dien  SERIAL PRIMARY KEY,
    ten_dao_dien VARCHAR(100) NOT NULL
);

-- Bảng 8: Bảng phim đạo diễn
CREATE TABLE phim_dao_dien
(
    id_phim     INT REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_dao_dien INT REFERENCES dao_dien (id_dao_dien) ON DELETE CASCADE,
    PRIMARY KEY (id_phim, id_dao_dien)
);

CREATE INDEX idx_phim_daodien_phim ON phim_dao_dien (id_phim);

-- Bảng 9: Bảng diễn viên
CREATE TABLE dien_vien
(
    id_dien_vien  SERIAL PRIMARY KEY,
    ten_dien_vien VARCHAR(100) NOT NULL
);

-- Bảng 10: Bảng phim diễn viên
CREATE TABLE phim_dien_vien
(
    id_phim      INT REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_dien_vien INT REFERENCES dien_vien (id_dien_vien) ON DELETE CASCADE,
    PRIMARY KEY (id_phim, id_dien_vien)
);

CREATE INDEX idx_phim_dienvien_phim ON phim_dien_vien (id_phim);

-- Bảng 11: Bảng hình ảnh
CREATE TABLE hinh_anh
(
    id_hinh_anh   SERIAL PRIMARY KEY,
    ten_hinh_anh  VARCHAR(100) NOT NULL,
    loai_hinh_anh VARCHAR(100) NOT NULL,
    url           VARCHAR(255),
    id_phim       INT REFERENCES phim (id_phim) ON DELETE CASCADE
);

-- Bảng 12: Bảng trailer
CREATE TABLE trailer
(
    id_trailer SERIAL PRIMARY KEY,
    url        TEXT NOT NULL,
    id_phim    INT  NOT NULL UNIQUE,
    CONSTRAINT fk_trailer_phim FOREIGN KEY (id_phim)
        REFERENCES phim (id_phim) ON DELETE CASCADE
);

-- Bảng 13: Bảng khách hàng
CREATE TABLE khach_hang
(
    id_khach_hang    SERIAL PRIMARY KEY,
    ten_khach_hang   VARCHAR(100) NOT NULL,
    email            VARCHAR(100) NOT NULL UNIQUE,
    so_dien_thoai    VARCHAR(15)  NOT NULL,
    ngay_sinh        DATE CHECK (ngay_sinh <= CURRENT_DATE),
    gioi_tinh        VARCHAR(10) CHECK (gioi_tinh IN ('Nam', 'Nu', 'Khac')),
    trang_thai       VARCHAR(20)           DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG', 'BI_CAM')),
    diem_tich_luy    INT                   DEFAULT 0 CHECK (diem_tich_luy >= 0),
    cccd             VARCHAR(12) UNIQUE,
    id_avatar        BIGINT,

    ngay_tao         DATE         NOT NULL DEFAULT CURRENT_DATE,
    hang_thanh_vien  VARCHAR(20)           DEFAULT 'Dong'
        CHECK (hang_thanh_vien IN ('Dong', 'Bac', 'Vang', 'Kim Cuong')),
    ghi_chu          TEXT,
    anh_dai_dien     VARCHAR(255),
    dia_chi          TEXT,
    ngay_cap_nhat    TIMESTAMP             DEFAULT CURRENT_TIMESTAMP,
    so_lan_mua_ve    INTEGER               DEFAULT 0,
    tong_tien_da_mua DECIMAL(15, 2)        DEFAULT 0.00
);

-- Hàm cập nhật hạng thành viên
CREATE OR REPLACE FUNCTION cap_nhat_hang_thanh_vien()
    RETURNS TRIGGER AS
$$
BEGIN
    -- Hệ thống phân loại khách hàng mới
    IF NEW.diem_tich_luy >= 1000 THEN
        NEW.hang_thanh_vien := 'KIM_CUONG';
    ELSIF NEW.diem_tich_luy >= 500 THEN
        NEW.hang_thanh_vien := 'VANG';
    ELSIF NEW.diem_tich_luy >= 100 THEN
        NEW.hang_thanh_vien := 'BAC';
ELSE
        NEW.hang_thanh_vien := 'DONG';
END IF;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger khi INSERT hoặc UPDATE diem_tich_luy
CREATE TRIGGER trg_cap_nhat_hang_thanh_vien
    BEFORE INSERT OR UPDATE OF diem_tich_luy
                     ON khach_hang
                         FOR EACH ROW
                         EXECUTE FUNCTION cap_nhat_hang_thanh_vien();

CREATE INDEX idx_khach_hang_email ON khach_hang (email);

-- Bảng 14: Bảng avatars
CREATE TABLE IF NOT EXISTS avatars
(
    id         BIGSERIAL PRIMARY KEY,
                                       ten_avatar VARCHAR(100) NOT NULL,
    url_avatar VARCHAR(500) NOT NULL,
    mo_ta      TEXT,
    trang_thai BOOLEAN      NOT NULL DEFAULT TRUE,
    ngay_tao   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

COMMENT ON TABLE avatars IS 'Bảng quản lý avatar cho khách hàng';
COMMENT ON COLUMN avatars.ten_avatar IS 'Tên avatar';
COMMENT ON COLUMN avatars.url_avatar IS 'URL hình ảnh avatar';
COMMENT ON COLUMN avatars.mo_ta IS 'Mô tả avatar';
COMMENT ON COLUMN avatars.trang_thai IS 'Trạng thái hoạt động của avatar';

-- Index cho bảng avatars
CREATE INDEX IF NOT EXISTS idx_avatars_trang_thai ON avatars (trang_thai);

-- Bảng 15: Bảng nhân viên
CREATE TABLE nhan_vien
(
    id_nhan_vien          SERIAL PRIMARY KEY,
    ten_nhan_vien         VARCHAR(100)        NOT NULL,
    email                 VARCHAR(100) UNIQUE NOT NULL,
    so_dien_thoai         VARCHAR(15)         NOT NULL,
    ngay_sinh             DATE CHECK (ngay_sinh <= CURRENT_DATE),
    gioi_tinh             VARCHAR(10) CHECK (gioi_tinh IN ('Nam', 'Nu', 'Khac')),
    cccd                  VARCHAR(20) UNIQUE,
    trang_thai            VARCHAR(20)    DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG')),
    ngay_vao_lam          DATE                NOT NULL CHECK (ngay_vao_lam <= CURRENT_DATE),
    chuc_vu               VARCHAR(50)         NOT NULL
        CHECK (chuc_vu IN ('THU_NGAN', 'SOAT_VE', 'BAN_BAP_NUOC', 'ONLINE_SUPPORT')),
    luong_co_ban          NUMERIC(15, 2) CHECK (luong_co_ban >= 0),
    loai_hop_dong         VARCHAR(50) CHECK (loai_hop_dong IN ('CHINH_THUC')),
    ngay_cap_nhat         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
    ghi_chu               TEXT,
    id_rap_chieu          INT                 NOT NULL REFERENCES rap_chieu (id_rap_chieu) ON DELETE CASCADE,
    anh_dai_dien          VARCHAR(255),
    dia_chi               TEXT,
    so_lan_ban_ve         INTEGER        DEFAULT 0,
    tong_doanh_thu_ban_ve DECIMAL(15, 2) DEFAULT 0.00
);

-- Bảng 16: Bảng tài khoản người dùng
CREATE TABLE tai_khoan_nguoi_dung
(
    id_user_account    SERIAL PRIMARY KEY,
    ten_dang_nhap      VARCHAR(100)                     NOT NULL UNIQUE,
    mat_khau           VARCHAR(255)                     NOT NULL,
    email              VARCHAR(100),
    lan_dang_nhap_cuoi TIMESTAMP,
    id_vai_tro         INT REFERENCES vai_tro (id_role) NOT NULL,
    id_khach_hang      INT REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    id_nhan_vien       INT REFERENCES nhan_vien (id_nhan_vien) ON DELETE CASCADE,
    trang_thai         VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG')),
    CONSTRAINT only_one_fk CHECK (
        (id_khach_hang IS NOT NULL AND id_nhan_vien IS NULL)
            OR (id_khach_hang IS NULL AND id_nhan_vien IS NOT NULL)
        )
);

-- Bổ sung cột thời gian cho tai_khoan_nguoi_dung (nếu thiếu)
ALTER TABLE tai_khoan_nguoi_dung
    ADD COLUMN IF NOT EXISTS ngay_tao TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ADD COLUMN IF NOT EXISTS ngay_cap_nhat TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

-- Cập nhật bảng tai_khoan_nguoi_dung để hỗ trợ social login
ALTER TABLE tai_khoan_nguoi_dung
    ADD COLUMN IF NOT EXISTS social_id       VARCHAR(100),
    ADD COLUMN IF NOT EXISTS social_provider VARCHAR(20) CHECK (social_provider IN ('GOOGLE', 'FACEBOOK')),
    ADD COLUMN IF NOT EXISTS avatar_url      VARCHAR(500),
    ADD COLUMN IF NOT EXISTS email_verified  BOOLEAN DEFAULT false,
    ADD COLUMN IF NOT EXISTS social_verified BOOLEAN DEFAULT false;

-- Tạo index cho social login
CREATE INDEX IF NOT EXISTS idx_tai_khoan_social_id ON tai_khoan_nguoi_dung (social_id, social_provider);

-- Bảng 17: Bảng tài khoản xã hội
CREATE TABLE IF NOT EXISTS tai_khoan_xa_hoi
(
    id_tai_khoan_xa_hoi                  SERIAL PRIMARY KEY,
    id_nguoi_dung                        INT          NOT NULL REFERENCES tai_khoan_nguoi_dung (id_user_account) ON DELETE CASCADE,
    nha_cung_cap                         VARCHAR(20)  NOT NULL CHECK (nha_cung_cap IN ('GOOGLE', 'FACEBOOK')),
    id_nguoi_dung_nha_cung_cap           VARCHAR(100) NOT NULL,
    email_nguoi_dung_nha_cung_cap        VARCHAR(255),
    ten_nguoi_dung_nha_cung_cap          VARCHAR(255),
    anh_dai_dien_nguoi_dung_nha_cung_cap VARCHAR(500),
    ma_truy_cap                          TEXT,
    ma_lay_lai                           TEXT,
    thoi_gian_het_han_ma                 TIMESTAMP,
    ngay_tao                             TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat                        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    trang_thai_hoat_dong                 BOOLEAN      NOT NULL DEFAULT true,
    UNIQUE (nha_cung_cap, id_nguoi_dung_nha_cung_cap)
    );

-- Index cho tai_khoan_xa_hoi
CREATE INDEX IF NOT EXISTS idx_tai_khoan_xa_hoi_nguoi_dung ON tai_khoan_xa_hoi (id_nguoi_dung);
CREATE INDEX IF NOT EXISTS idx_tai_khoan_xa_hoi_nha_cung_cap ON tai_khoan_xa_hoi (nha_cung_cap);
CREATE INDEX IF NOT EXISTS idx_tai_khoan_xa_hoi_id_nguoi_dung_nha_cung_cap ON tai_khoan_xa_hoi (id_nguoi_dung_nha_cung_cap);

-- Trigger để cập nhật updated_at
CREATE OR REPLACE FUNCTION cap_nhat_ngay_cap_nhat_tai_khoan_xa_hoi()
    RETURNS TRIGGER AS
$$
BEGIN
    NEW.ngay_cap_nhat = CURRENT_TIMESTAMP;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cap_nhat_ngay_cap_nhat_tai_khoan_xa_hoi
    BEFORE UPDATE
    ON tai_khoan_xa_hoi
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat_tai_khoan_xa_hoi();

-- Bảng 18: Bảng voucher
CREATE TABLE voucher
(
    id_voucher      SERIAL PRIMARY KEY,
    ten_voucher     VARCHAR(100) NOT NULL UNIQUE,
    phan_tram_giam  DECIMAL(5, 2) CHECK (phan_tram_giam >= 0 AND phan_tram_giam <= 100),
    muc_giam_toi_da DECIMAL(15, 2) CHECK (muc_giam_toi_da >= 0),
    so_tien_giam    DECIMAL(15, 2) CHECK (so_tien_giam >= 0),
    ngay_bat_dau    DATE         NOT NULL,
    ngay_ket_thuc   DATE         NOT NULL,
    trang_thai      VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'HET_HAN', 'DA_SU_DUNG')),
    so_luong        INT          NOT NULL CHECK (so_luong >= 0),
    dieu_kien_giam  TEXT,
    ngay_tao        DATE         NOT NULL CHECK (ngay_tao <= CURRENT_DATE),
    CONSTRAINT valid_ngay CHECK (ngay_bat_dau <= ngay_ket_thuc),
    CONSTRAINT at_least_one_discount CHECK (phan_tram_giam IS NOT NULL OR so_tien_giam IS NOT NULL)
);

-- Trigger: Tự động cập nhật trạng thái Voucher khi hết hạn
CREATE OR REPLACE FUNCTION cap_nhat_trang_thai_voucher()
    RETURNS TRIGGER AS
$$
BEGIN
    IF NEW.ngay_ket_thuc < CURRENT_DATE THEN
        NEW.trang_thai := 'HET_HAN';
END IF;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;


CREATE TRIGGER trg_voucher_het_han
    AFTER INSERT OR UPDATE
                        ON Voucher
                        FOR EACH ROW
                        EXECUTE FUNCTION cap_nhat_trang_thai_voucher();


-- Bảng 19: Bảng khách hàng voucher
CREATE TABLE khach_hang_voucher
(
    id_khach_hang INT REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    id_voucher    INT REFERENCES voucher (id_voucher) ON DELETE CASCADE,
    ngay_nhan     DATE        DEFAULT CURRENT_DATE,
    trang_thai    VARCHAR(50) DEFAULT 'CHUA_SU_DUNG',
    PRIMARY KEY (id_khach_hang, id_voucher)
);

-- Bảng 20: Bảng hóa đơn
CREATE TABLE hoa_don
(
    id_hoa_don             SERIAL PRIMARY KEY,
    ten_hoa_don            VARCHAR(100)   NOT NULL,
    tong_tien              DECIMAL(15, 2) NOT NULL CHECK (tong_tien >= 0),
    tien_giam              DECIMAL(15, 2) CHECK (tien_giam >= 0),
    ngay_dat               DATE           NOT NULL CHECK (ngay_dat <= CURRENT_DATE),
    loai_hoa_don           VARCHAR(50)    NOT NULL CHECK (loai_hoa_don IN ('Online', 'Tai_Quay')),
    so_dien_thoai          VARCHAR(15)    NOT NULL,
    ten_khach_hang         VARCHAR(100)   NOT NULL,
    trang_thai             VARCHAR(20) DEFAULT 'CHO_THANH_TOAN'
        CHECK (trang_thai IN ('CHO_THANH_TOAN', 'DA_THANH_TOAN', 'DA_HUY')),
    id_khach_hang          INT            REFERENCES khach_hang (id_khach_hang) ON DELETE SET NULL,
    id_nhan_vien           INT            REFERENCES nhan_vien (id_nhan_vien) ON DELETE SET NULL,
    id_voucher             INT            REFERENCES voucher (id_voucher) ON DELETE SET NULL,
    -- Constraint logic sẽ được sửa ở dưới
    -- ma_giao_dich_vnpay đã được thay thế bằng ma_giao_dich ở dưới
    ngay_tao               TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat          TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ghi_chu                TEXT,
    phuong_thuc_thanh_toan VARCHAR(50),
    trang_thai_thanh_toan  VARCHAR(20) DEFAULT 'CHO_THANH_TOAN'
);

-- Bảng 21: Bảng thanh toán
CREATE TABLE thanh_toan
(
    id_thanh_toan          SERIAL PRIMARY KEY,
    id_hoa_don             INT            NOT NULL REFERENCES hoa_don (id_hoa_don) ON DELETE CASCADE,
    phuong_thuc_thanh_toan VARCHAR(50)    NOT NULL,
    ngay_thanh_toan        DATE           NOT NULL CHECK (ngay_thanh_toan <= CURRENT_DATE),
    so_tien                DECIMAL(15, 2) NOT NULL CHECK (so_tien >= 0),
    trang_thai             VARCHAR(20) DEFAULT 'CHO_XU_LY'
        CHECK (trang_thai IN ('CHO_XU_LY', 'HOAN_THANH', 'DA_HUY'))
);


-- Bảng 22: Bảng ghế ngồi
CREATE TABLE ghe_ngoi
(
    id_ghe_ngoi    SERIAL PRIMARY KEY,
    hang_ghe       VARCHAR(10)    NOT NULL,                  -- A, B, C, D, ...
    so_ghe         VARCHAR(10)    NOT NULL,                  -- 1, 2, 3, 4, ...
    id_phong_chieu INT            NOT NULL REFERENCES phong_chieu (id_phong_chieu) ON DELETE CASCADE,
    trang_thai     VARCHAR(20)             DEFAULT 'CON_TRONG'
        CHECK (trang_thai IN ('CON_TRONG', 'DA_DAT', 'DANG_SU_DUNG', 'DANG_GIU')),
    loai_ghe       VARCHAR(50)    NOT NULL CHECK (loai_ghe IN ('Thuong', 'VIP', 'GheDoi')),
    gia_ghe_co_ban DECIMAL(10, 2) NOT NULL DEFAULT 50000.00, -- Giá cơ bản của ghế
    hold_time      TIMESTAMP,                                -- Thời gian giữ ghế
    hold_user_id   INT,                                      -- ID người dùng đang giữ ghế
    ngay_tao       TIMESTAMP               DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat  TIMESTAMP               DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_ghe_phong UNIQUE (id_phong_chieu, hang_ghe, so_ghe)
);

-- Comments để giải thích
COMMENT ON TABLE ghe_ngoi IS 'Bảng quản lý ghế ngồi theo layout Excel-like (A1, A2, B1, B2...)';
COMMENT ON COLUMN ghe_ngoi.hang_ghe IS 'Hàng ghế (A, B, C, D...) - tương ứng với hàng trong Excel';
COMMENT ON COLUMN ghe_ngoi.so_ghe IS 'Số ghế (1, 2, 3, 4...) - tương ứng với cột trong Excel';
COMMENT ON COLUMN ghe_ngoi.gia_ghe_co_ban IS 'Giá cơ bản của ghế (VNĐ) - có thể thay đổi theo suất chiếu';
COMMENT ON COLUMN ghe_ngoi.hold_time IS 'Thời gian bắt đầu giữ ghế';
COMMENT ON COLUMN ghe_ngoi.hold_user_id IS 'ID người dùng đang giữ ghế';

-- Bảng 23: Bảng suất chiếu
CREATE TABLE suat_chieu
(
    id_suat_chieu      SERIAL PRIMARY KEY,
    ten_suat_chieu     VARCHAR(100) NOT NULL,
    ngay_chieu         DATE         NOT NULL CHECK (ngay_chieu >= CURRENT_DATE),
    -- gio_chieu đã được gộp vào thoi_gian_bat_dau
    thoi_gian_bat_dau  TIME         NOT NULL,
    thoi_gian_ket_thuc TIME         NOT NULL,
    trang_thai         VARCHAR(20)           DEFAULT 'DA_LEN_LICH'
        CHECK (trang_thai IN ('DA_LEN_LICH', 'DANG_CHIEU', 'HOAN_THANH', 'DA_HUY')),
    id_phim            INT          NOT NULL REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_phong_chieu     INT          NOT NULL REFERENCES phong_chieu (id_phong_chieu) ON DELETE CASCADE,
    CONSTRAINT valid_thoi_gian CHECK (thoi_gian_bat_dau < thoi_gian_ket_thuc),
    CONSTRAINT suat_chieu_thoi_gian_hop_ly CHECK (
        thoi_gian_ket_thuc > thoi_gian_bat_dau AND
        ngay_chieu >= CURRENT_DATE - INTERVAL '1 day'
        ),
    so_ghe_con_trong   INTEGER      NOT NULL DEFAULT 0,
    tong_so_ghe        INTEGER      NOT NULL DEFAULT 0,
    ngay_tao           TIMESTAMP             DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat      TIMESTAMP             DEFAULT CURRENT_TIMESTAMP,
    ghi_chu            TEXT
);

-- Trigger: Tự động tạo giá vé mặc định khi tạo suất chiếu mới
CREATE OR REPLACE FUNCTION trigger_tao_gia_ve_mac_dinh()
    RETURNS TRIGGER AS
$$
BEGIN
    -- Tự động tạo giá vé mặc định cho suất chiếu mới
    PERFORM ap_dung_gia_ve_mac_dinh(NEW.id_suat_chieu);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_tao_gia_ve_mac_dinh
    AFTER INSERT
    ON suat_chieu
    FOR EACH ROW
EXECUTE FUNCTION trigger_tao_gia_ve_mac_dinh();

CREATE INDEX idx_suat_chieu_ngay ON suat_chieu (ngay_chieu);


-- Bảng 24: Bảng giá vé suất chiếu
CREATE TABLE gia_ve_suat_chieu
(
    id_gia_ve      SERIAL PRIMARY KEY,
    id_suat_chieu  INT            NOT NULL REFERENCES suat_chieu (id_suat_chieu) ON DELETE CASCADE,
    loai_ghe       VARCHAR(50)    NOT NULL CHECK (loai_ghe IN ('Thuong', 'VIP', 'GheDoi')),
    gia_ve         DECIMAL(10, 2) NOT NULL CHECK (gia_ve > 0),
    phan_tram_giam DECIMAL(5, 2) DEFAULT 0.00 CHECK (phan_tram_giam >= 0 AND phan_tram_giam <= 100),
    gia_sau_giam   DECIMAL(10, 2) GENERATED ALWAYS AS (gia_ve * (1 - phan_tram_giam / 100)) STORED,
    ngay_tao       TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_gia_ve_suat_loai UNIQUE (id_suat_chieu, loai_ghe)
);

COMMENT ON TABLE gia_ve_suat_chieu IS 'Bảng quản lý giá vé linh hoạt theo từng suất chiếu';
COMMENT ON COLUMN gia_ve_suat_chieu.gia_ve IS 'Giá vé gốc (VNĐ)';
COMMENT ON COLUMN gia_ve_suat_chieu.phan_tram_giam IS 'Phần trăm giảm giá (0-100)';
COMMENT ON COLUMN gia_ve_suat_chieu.gia_sau_giam IS 'Giá vé sau khi giảm (tự động tính)';

-- Index cho bảng giá vé
CREATE INDEX IF NOT EXISTS idx_gia_ve_suat_chieu ON gia_ve_suat_chieu (id_suat_chieu);
CREATE INDEX IF NOT EXISTS idx_gia_ve_loai_ghe ON gia_ve_suat_chieu (loai_ghe);

-- Index để tối ưu truy vấn
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_phong ON ghe_ngoi (id_phong_chieu);
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_trang_thai ON ghe_ngoi (trang_thai);
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_loai ON ghe_ngoi (loai_ghe);
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_hold_user ON ghe_ngoi (hold_user_id);

-- View: Hiển thị layout ghế theo phòng chiếu
CREATE OR REPLACE VIEW v_layout_ghe_phong AS
SELECT id_phong_chieu,
    hang_ghe,
    string_agg(
            CASE
                WHEN trang_thai = 'CON_TRONG' THEN so_ghe || '(' || loai_ghe || ')'
                WHEN trang_thai = 'DA_DAT' THEN so_ghe || '[ĐÃ ĐẶT]'
                WHEN trang_thai = 'DANG_GIU' THEN so_ghe || '[ĐANG GIỮ]'
                ELSE so_ghe || '[ĐANG SỬ DỤNG]'
                END,
            ' ' ORDER BY so_ghe::integer
    ) as layout_hang
FROM ghe_ngoi
GROUP BY id_phong_chieu, hang_ghe
ORDER BY id_phong_chieu, hang_ghe;

-- Function: Tự động giải phóng ghế đã giữ quá lâu (15 phút)
CREATE OR REPLACE FUNCTION giai_phong_ghe_het_han()
    RETURNS INTEGER AS
$$
DECLARE
so_ghe_da_giai_phong INTEGER := 0;
BEGIN
UPDATE ghe_ngoi
    SET trang_thai    = 'CON_TRONG',
        hold_time     = NULL,
        hold_user_id  = NULL,
    ngay_cap_nhat = CURRENT_TIMESTAMP
WHERE trang_thai = 'DANG_GIU'
  AND hold_time < CURRENT_TIMESTAMP - INTERVAL '15 minutes';

GET DIAGNOSTICS so_ghe_da_giai_phong = ROW_COUNT;
RETURN so_ghe_da_giai_phong;
END;
$$ LANGUAGE plpgsql;

-- Function: Tính giá vé động cho ghế theo suất chiếu
CREATE OR REPLACE FUNCTION tinh_gia_ve_ghe(
    p_id_ghe_ngoi INT,
    p_id_suat_chieu INT
)
    RETURNS DECIMAL(10, 2) AS
$$
DECLARE
    gia_ve_tinh   DECIMAL(10, 2) := 0;
    loai_ghe_ngoi VARCHAR(50);
BEGIN
    -- Lấy loại ghế
    SELECT loai_ghe
    INTO loai_ghe_ngoi
FROM ghe_ngoi
WHERE id_ghe_ngoi = p_id_ghe_ngoi;

-- Lấy giá vé từ bảng gia_ve_suat_chieu
    SELECT gia_sau_giam
    INTO gia_ve_tinh
FROM gia_ve_suat_chieu
WHERE id_suat_chieu = p_id_suat_chieu
  AND loai_ghe = loai_ghe_ngoi;

-- Nếu không có giá riêng, dùng giá cơ bản
IF gia_ve_tinh IS NULL OR gia_ve_tinh = 0 THEN
        SELECT gia_ghe_co_ban
        INTO gia_ve_tinh
FROM ghe_ngoi
WHERE id_ghe_ngoi = p_id_ghe_ngoi;
END IF;

RETURN COALESCE(gia_ve_tinh, 50000.00);
END;
$$ LANGUAGE plpgsql;

-- Function: Áp dụng giá vé mặc định cho suất chiếu mới
CREATE OR REPLACE FUNCTION ap_dung_gia_ve_mac_dinh(p_id_suat_chieu INT)
    RETURNS VOID AS
$$
BEGIN
    -- Áp dụng giá vé mặc định cho các loại ghế
INSERT INTO gia_ve_suat_chieu (id_suat_chieu, loai_ghe, gia_ve, phan_tram_giam)
    VALUES (p_id_suat_chieu, 'Thuong', 50000.00, 0.00),
    (p_id_suat_chieu, 'VIP', 80000.00, 0.00),
    (p_id_suat_chieu, 'GheDoi', 100000.00, 0.00)
    ON CONFLICT (id_suat_chieu, loai_ghe) DO NOTHING;
END;
$$ LANGUAGE plpgsql;

-- Bảng 25: Bảng vé phim
CREATE TABLE ve_phim
(
    id_ve_phim            SERIAL PRIMARY KEY,
    gia_ve                DECIMAL(15, 2) NOT NULL CHECK (gia_ve >= 0),
    ngay_dat              DATE           NOT NULL CHECK (ngay_dat <= CURRENT_DATE),
    id_suat_chieu         INT            NOT NULL REFERENCES suat_chieu (id_suat_chieu) ON DELETE CASCADE,
    id_khach_hang         INT            NOT NULL REFERENCES khach_hang (id_khach_hang),
    id_ghe_ngoi           INT            NOT NULL REFERENCES ghe_ngoi (id_ghe_ngoi) ON DELETE CASCADE,
    id_hoa_don            INT            NOT NULL REFERENCES hoa_don (id_hoa_don) ON DELETE CASCADE,
    id_phim               INT            NOT NULL REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_nhan_vien          INT REFERENCES nhan_vien (id_nhan_vien), -- NULL cho vé online
    id_phong_chieu        INT            NOT NULL REFERENCES phong_chieu (id_phong_chieu) ON DELETE CASCADE,
    trang_thai            VARCHAR(20) DEFAULT 'CON_TRONG'
        CHECK (trang_thai IN ('CON_TRONG', 'DA_BAN', 'DA_DAT')),
    ma_ve                 VARCHAR(50) UNIQUE,
    ngay_tao              TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat         TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ghi_chu               TEXT,
    trang_thai_thanh_toan VARCHAR(20) DEFAULT 'CHO_THANH_TOAN',
    CONSTRAINT ve_phim_trang_thai_logic CHECK (
        (trang_thai = 'DA_DAT' AND ma_ve IS NOT NULL) OR
        (trang_thai = 'DA_BAN' AND ma_ve IS NOT NULL) OR
        (trang_thai = 'CON_TRONG')
        ),
    CONSTRAINT ve_phim_gia_hop_ly CHECK (gia_ve >= 10000 AND gia_ve <= 1000000)
);

CREATE INDEX idx_vephim_id_hoa_don ON ve_phim (id_hoa_don);


-- Trigger: Tự động cập nhật trạng thái VePhim thành da_ban sau khi thanh toán
CREATE OR REPLACE FUNCTION cap_nhat_trang_thai_ve_sau_thanh_toan()
    RETURNS TRIGGER AS
$$
BEGIN
    IF NEW.trang_thai = 'HOAN_THANH' THEN
UPDATE ve_phim
SET trang_thai = 'DA_BAN'
WHERE id_hoa_don = NEW.id_hoa_don;
END IF;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cap_nhat_ve
    AFTER UPDATE
    ON thanh_toan
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_trang_thai_ve_sau_thanh_toan();

-- View: Danh sách hóa đơn đã thanh toán kèm khách hàng
-- (removed duplicate) CREATE OR REPLACE VIEW v_danh_sach_hoa_don_thanh_toan AS ...


-- View: Lịch chiếu hôm nay
CREATE VIEW v_lich_chieu_hom_nay AS
SELECT s.id_suat_chieu,
       s.ten_suat_chieu,
       p.ten_phim,
       s.ngay_chieu,
       s.thoi_gian_bat_dau,
       pc.ten_phong_chieu,
       r.ten_rap_chieu
FROM suat_chieu s
         JOIN phim p ON s.id_phim = p.id_phim
         JOIN phong_chieu pc ON s.id_phong_chieu = pc.id_phong_chieu
         JOIN rap_chieu r ON pc.id_rap_chieu = r.id_rap_chieu
WHERE s.ngay_chieu = CURRENT_DATE;

-- Bảng 26: Bảng combo ăn uống
CREATE TABLE combo_an_uong
(
    id_combo      SERIAL PRIMARY KEY,
    ten_combo     VARCHAR(100)   NOT NULL,
    mo_ta         TEXT,
    gia_combo     DECIMAL(10, 2) NOT NULL CHECK (gia_combo > 0),
    trang_thai    VARCHAR(20) DEFAULT 'HOAT_DONG' CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG')),
    ngay_tao      TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 27: Bảng đánh giá phim
CREATE TABLE danh_gia_phim
(
    id_danh_gia       SERIAL PRIMARY KEY,
    id_phim           INT     NOT NULL REFERENCES phim (id_phim) ON DELETE CASCADE,
    id_khach_hang     INT     NOT NULL REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    so_sao            INTEGER NOT NULL CHECK (so_sao >= 1 AND so_sao <= 5),
                               noi_dung_danh_gia TEXT,
    ngay_danh_gia     TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    trang_thai        VARCHAR(20) DEFAULT 'HOAT_DONG',
    tieu_de_danh_gia  VARCHAR(100),
    co_anh_kem_theo   BOOLEAN     DEFAULT FALSE,
    so_luot_thich     INTEGER     DEFAULT 0,
    so_luot_phan_hoi  INTEGER     DEFAULT 0,
    da_xem_phim       BOOLEAN     DEFAULT FALSE,
    ngay_xem_phim     TIMESTAMP,
    rap_chieu         VARCHAR(100),
    loai_ve           VARCHAR(20),
    gia_ve            DECIMAL(10, 2),
                               UNIQUE (id_phim, id_khach_hang)
);

-- Bảng 28: Bảng hóa đơn combo
CREATE TABLE IF NOT EXISTS hoa_don_combo
(
    id_hoa_don INT            NOT NULL REFERENCES hoa_don (id_hoa_don) ON DELETE CASCADE,
    id_combo   INT            NOT NULL REFERENCES combo_an_uong (id_combo) ON DELETE CASCADE,
    so_luong   INTEGER        NOT NULL DEFAULT 1 CHECK (so_luong > 0),
    gia_combo  DECIMAL(10, 2) NOT NULL CHECK (gia_combo > 0),
    PRIMARY KEY (id_hoa_don, id_combo)
    );

-- Bảng 29: Bảng checkin vé
CREATE TABLE checkin_ve
(
    id_checkin           SERIAL PRIMARY KEY,
    id_ve_phim           INT       NOT NULL REFERENCES ve_phim (id_ve_phim) ON DELETE CASCADE,
    thoi_gian_checkin    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    trang_thai           VARCHAR(20)        DEFAULT 'DA_CHECKIN'
        CHECK (trang_thai IN ('DA_CHECKIN', 'DA_HUY')),
    ghi_chu              TEXT,
    id_nhan_vien_checkin INT REFERENCES nhan_vien (id_nhan_vien),
    CONSTRAINT unique_ve_checkin UNIQUE (id_ve_phim)
);

-- Bảng 30: Bảng OTP codes
CREATE TABLE otp_codes
(
    id         SERIAL PRIMARY KEY,
    phone      VARCHAR(15) NOT NULL,
    otp_code   VARCHAR(10) NOT NULL,
                           created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP   NOT NULL,
    is_used    BOOLEAN   DEFAULT FALSE
);
-- Seed otp_codes (idempotent)
INSERT INTO otp_codes (phone, otp_code, created_at, expires_at, is_used)
VALUES ('0912345678', '123456', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + INTERVAL '10 minutes', false),
       ('0987654321', '654321', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + INTERVAL '10 minutes', false)
ON CONFLICT DO NOTHING;


-- Bảng 31: Bảng review images
CREATE TABLE review_images
(
    id           SERIAL PRIMARY KEY,
    id_danh_gia  INT          NOT NULL REFERENCES danh_gia_phim (id_danh_gia) ON DELETE CASCADE,
                               url_hinh_anh VARCHAR(500) NOT NULL,
    mo_ta        TEXT,
    ngay_tao     TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
-- Seed review_images
INSERT INTO review_images (id_danh_gia, url_hinh_anh, mo_ta)
SELECT dg.id_danh_gia, '/uploads/reviews/sample_' || dg.id_danh_gia || '.jpg', 'Ảnh minh họa'
FROM danh_gia_phim dg
WHERE dg.id_danh_gia IN (SELECT id_danh_gia FROM danh_gia_phim LIMIT 2)
  AND NOT EXISTS (
        SELECT 1 FROM review_images ri WHERE ri.id_danh_gia = dg.id_danh_gia
);

-- Bảng 32: Bảng review replies
CREATE TABLE review_replies
(
    id                SERIAL PRIMARY KEY,
    id_danh_gia       INT  NOT NULL REFERENCES danh_gia_phim (id_danh_gia) ON DELETE CASCADE,
    id_nhan_vien      INT REFERENCES nhan_vien (id_nhan_vien),
                                noi_dung_phan_hoi TEXT NOT NULL,
    ngay_phan_hoi     TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    trang_thai        VARCHAR(20) DEFAULT 'HOAT_DONG' CHECK (trang_thai IN ('HOAT_DONG', 'KHONG_HOAT_DONG'))
);
-- Seed review_replies (map to any available ONLINE_SUPPORT)
INSERT INTO review_replies (id_danh_gia, id_nhan_vien, noi_dung_phan_hoi)
SELECT dg.id_danh_gia,
       (SELECT id_nhan_vien FROM nhan_vien WHERE chuc_vu = 'ONLINE_SUPPORT' ORDER BY id_nhan_vien LIMIT 1),
       'Cảm ơn bạn đã đánh giá!'
FROM danh_gia_phim dg
WHERE dg.id_danh_gia IN (SELECT id_danh_gia FROM danh_gia_phim LIMIT 2)
  AND NOT EXISTS (
        SELECT 1 FROM review_replies rr WHERE rr.id_danh_gia = dg.id_danh_gia
);

-- Bảng 33: Bảng chiến dịch khuyến mãi
CREATE TABLE chien_dich_khuyen_mai
(
    id_chien_dich  SERIAL PRIMARY KEY,
                                       ten_chien_dich VARCHAR(100) NOT NULL,
    mo_ta          TEXT,
    ngay_bat_dau   DATE         NOT NULL,
    ngay_ket_thuc  DATE         NOT NULL,
    trang_thai     VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'HET_HAN', 'CHUA_AP_DUNG')),
    ngay_tao       TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat  TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 34: Bảng khuyến mãi
CREATE TABLE khuyen_mai
(
    id_khuyen_mai       SERIAL PRIMARY KEY,
    id_chien_dich       INT            NOT NULL REFERENCES chien_dich_khuyen_mai (id_chien_dich) ON DELETE CASCADE,
    loai_khuyen_mai     VARCHAR(20)    NOT NULL
        CHECK (loai_khuyen_mai IN ('PHAN_TRAM', 'TIEN_MAT')),
    gia_tri             NUMERIC(10, 2) NOT NULL CHECK (gia_tri > 0),
    mo_ta               TEXT,
    trang_thai          VARCHAR(20) DEFAULT 'HOAT_DONG'
        CHECK (trang_thai IN ('HOAT_DONG', 'HET_HAN', 'CHUA_AP_DUNG')),
    so_luong_toi_da     INTEGER     DEFAULT 0 CHECK (so_luong_toi_da >= 0),
    so_luong_da_su_dung INTEGER     DEFAULT 0 CHECK (so_luong_da_su_dung >= 0),
    ngay_tao            TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat       TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 35: Bảng khuyến mãi theo đối tượng
CREATE TABLE khuyen_mai_doi_tuong
(
    id_doi_tuong  SERIAL PRIMARY KEY,
    id_khuyen_mai INT         NOT NULL REFERENCES khuyen_mai (id_khuyen_mai) ON DELETE CASCADE,
    doi_tuong     VARCHAR(20) NOT NULL
        CHECK (doi_tuong IN ('SINH_VIEN', 'TRE_EM', 'NGUOI_CAO_TUOI', 'VIP')),
    ngay_tao      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 36: Bảng lịch sử sử dụng khuyến mãi
CREATE TABLE lich_su_khuyen_mai
(
    id_lich_su    SERIAL PRIMARY KEY,
    id_khuyen_mai INT            NOT NULL REFERENCES khuyen_mai (id_khuyen_mai),
    id_ve_phim    INT            NOT NULL REFERENCES ve_phim (id_ve_phim),
    id_khach_hang INT            NOT NULL REFERENCES khach_hang (id_khach_hang),
    so_tien_giam  DECIMAL(10, 2) NOT NULL CHECK (so_tien_giam >= 0),
    ngay_su_dung  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 37: Bảng review media
CREATE TABLE review_media
(
    id               BIGSERIAL PRIMARY KEY,
    id_danh_gia      INTEGER      NOT NULL REFERENCES danh_gia_phim (id_danh_gia) ON DELETE CASCADE,
    url_media        VARCHAR(500) NOT NULL,
    loai_media       VARCHAR(20)  NOT NULL CHECK (loai_media IN ('IMAGE', 'VIDEO')),
    mo_ta            TEXT,
    thoi_luong_video INTEGER,     -- Thời lượng video (giây)
    kich_thuoc_file  BIGINT,      -- Kích thước file (bytes)
    duoi_file        VARCHAR(10), -- .jpg, .mp4, etc.
    ngay_tao         TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 38: Bảng review tags
CREATE TABLE review_tags
(
    id              BIGSERIAL PRIMARY KEY,
    id_danh_gia     INTEGER     NOT NULL REFERENCES danh_gia_phim (id_danh_gia) ON DELETE CASCADE,
    ten_tag         VARCHAR(50) NOT NULL,
    mau_sac         VARCHAR(20),
    so_luot_su_dung INTEGER   DEFAULT 0,
    ngay_tao        TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 39: Bảng user badges
CREATE TABLE user_badges
(
    id            BIGSERIAL PRIMARY KEY,
    id_khach_hang INTEGER      NOT NULL REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    ten_badge     VARCHAR(100) NOT NULL,
    mo_ta         TEXT,
    icon_url      VARCHAR(500),
    loai_badge    VARCHAR(50),
    diem_cong     INTEGER   DEFAULT 0,
    ngay_nhan     TIMESTAMP,
    ngay_tao      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 40: Bảng AI summaries
CREATE TABLE ai_summaries
(
    id                  BIGSERIAL PRIMARY KEY,
    id_phim             INTEGER NOT NULL REFERENCES phim (id_phim) ON DELETE CASCADE,
    noi_dung_tong_hop   TEXT,
    danh_gia_tong_the   NUMERIC(4, 1) DEFAULT 0,
    danh_gia_thong_diep NUMERIC(4, 1) DEFAULT 0,
    danh_gia_kich_ban   NUMERIC(4, 1) DEFAULT 0,
    danh_gia_cam_xuc    NUMERIC(4, 1) DEFAULT 0,
    so_luot_thich       INTEGER       DEFAULT 0,
    so_luot_khong_thich INTEGER       DEFAULT 0,
    trang_thai          VARCHAR(20)   DEFAULT 'HOAT_DONG',
    ngay_tao            TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat       TIMESTAMP
);

-- Bảng 41: Bảng quy tắc điểm thưởng
CREATE TABLE quy_tac_diem_thuong
(
    id             BIGSERIAL PRIMARY KEY,
    ten_quy_tac    VARCHAR(100) NOT NULL,
    mo_ta          TEXT,
    loai_hanh_dong VARCHAR(50)  NOT NULL, -- REVIEW, XEM_PHIM, TAN_GIA, etc.
    dieu_kien      TEXT,                  -- Điều kiện để nhận điểm
    so_diem        INTEGER      NOT NULL DEFAULT 0,
    trang_thai     VARCHAR(20)           DEFAULT 'HOAT_DONG',
    ngay_tao       TIMESTAMP             DEFAULT CURRENT_TIMESTAMP,
    ngay_cap_nhat  TIMESTAMP
);

-- Bảng 42: Bảng lịch sử điểm thưởng
CREATE TABLE lich_su_diem_thuong
(
    id             BIGSERIAL PRIMARY KEY,
    id_khach_hang  INTEGER     NOT NULL REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    id_quy_tac     INTEGER     REFERENCES quy_tac_diem_thuong (id) ON DELETE SET NULL,
                                     loai_hanh_dong VARCHAR(50) NOT NULL,
    so_diem        INTEGER     NOT NULL,
    mo_ta          TEXT,
    id_tham_chieu  INTEGER, -- ID của hành động gây ra điểm (review, vé, etc.)
    ngay_nhan      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Bảng 43: Bảng phòng chat
CREATE TABLE phong_chat
(
    id_phong_chat           SERIAL PRIMARY KEY,
    ma_phong_chat           VARCHAR(50) UNIQUE NOT NULL,
    ten_phong_chat          VARCHAR(200),
    loai_phong_chat         VARCHAR(50)        NOT NULL DEFAULT 'HO_TRO_KHACH_HANG',
    id_khach_hang           INT REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE,
    id_nhan_vien            INT                REFERENCES nhan_vien (id_nhan_vien) ON DELETE SET NULL,
    dang_hoat_dong          BOOLEAN            NOT NULL DEFAULT true,
    thoi_gian_tin_nhan_cuoi TIMESTAMP                   DEFAULT CURRENT_TIMESTAMP,
    thoi_gian_tao           TIMESTAMP          NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_gian_dong          TIMESTAMP,
    trang_thai              VARCHAR(20)                 DEFAULT 'MO' CHECK (trang_thai IN ('MO', 'DONG', 'CHO_XU_LY')),
    muc_do_uu_tien          VARCHAR(20)                 DEFAULT 'BINH_THUONG' CHECK (muc_do_uu_tien IN ('THAP', 'BINH_THUONG', 'CAO', 'KHAN_CAP')),
    nhan_dan                TEXT
);

-- Bảng 44: Bảng tin nhắn chat
CREATE TABLE tin_nhan_chat
(
    id_tin_nhan          SERIAL PRIMARY KEY,
    ma_phong_chat        VARCHAR(50)  NOT NULL REFERENCES phong_chat (ma_phong_chat) ON DELETE CASCADE,
    id_nguoi_gui         INT          REFERENCES tai_khoan_nguoi_dung (id_user_account) ON DELETE SET NULL,
    ten_nguoi_gui        VARCHAR(100) NOT NULL,
    loai_nguoi_gui       VARCHAR(20)  NOT NULL CHECK (loai_nguoi_gui IN ('KHACH_HANG', 'NHAN_VIEN', 'QUAN_TRI', 'HE_THONG')),
    noi_dung_tin_nhan    TEXT         NOT NULL,
    loai_tin_nhan        VARCHAR(20)  NOT NULL DEFAULT 'VAN_BAN' CHECK (loai_tin_nhan IN ('VAN_BAN', 'HINH_ANH', 'TAP_TIN', 'HE_THONG')),
    url_tap_tin          VARCHAR(500),
    ten_tap_tin          VARCHAR(200),
    kich_thuoc_tap_tin   BIGINT,
    da_doc               BOOLEAN      NOT NULL DEFAULT false,
    da_xoa               BOOLEAN      NOT NULL DEFAULT false,
    thoi_gian_tao        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_gian_doc        TIMESTAMP,
    id_tin_nhan_phan_hoi INT          REFERENCES tin_nhan_chat (id_tin_nhan) ON DELETE SET NULL,
    trang_thai_tin_nhan  VARCHAR(20)           DEFAULT 'DA_GUI' CHECK (trang_thai_tin_nhan IN ('DA_GUI', 'DA_NHAN', 'DA_DOC', 'THAT_BAI'))
);

-- Bảng 45: Bảng phòng chat nhân viên
CREATE TABLE phong_chat_nhan_vien
(
                                      id_phong_chat_nhan_vien SERIAL PRIMARY KEY,
    id_phong_chat           INT NOT NULL REFERENCES phong_chat (id_phong_chat) ON DELETE CASCADE,
    id_nhan_vien            INT NOT NULL REFERENCES nhan_vien (id_nhan_vien) ON DELETE CASCADE,
    vai_tro                 VARCHAR(20) CHECK (vai_tro IN ('NHAN_VIEN_CHINH', 'NHAN_VIEN_PHU')) DEFAULT 'NHAN_VIEN_PHU',
    ngay_tham_gia           TIMESTAMP                                                           DEFAULT CURRENT_TIMESTAMP
);
-- Seed phong_chat_nhan_vien: gán nhân viên ONLINE_SUPPORT vào tối đa 15 phòng chưa có
INSERT INTO phong_chat_nhan_vien (id_phong_chat, id_nhan_vien, vai_tro)
SELECT pc.id_phong_chat,
       (SELECT id_nhan_vien FROM nhan_vien WHERE chuc_vu = 'ONLINE_SUPPORT' ORDER BY id_nhan_vien LIMIT 1),
       'NHAN_VIEN_CHINH'
FROM phong_chat pc
WHERE pc.id_nhan_vien IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM phong_chat_nhan_vien pcnv WHERE pcnv.id_phong_chat = pc.id_phong_chat
  )
LIMIT 3;

