-- Bảng 47: Bảng email history
CREATE TABLE IF NOT EXISTS email_history
(
    id_email         SERIAL PRIMARY KEY,
    hoa_don_id       INT REFERENCES hoa_don (id_hoa_don) ON DELETE CASCADE,
    template_id      INT REFERENCES email_templates (id_template),
    email_nguoi_nhan VARCHAR(255) NOT NULL,
    tieu_de          VARCHAR(200) NOT NULL,
    noi_dung_html    TEXT,
    noi_dung_text    TEXT,
