SELECT h.id_hoa_don,
       (SELECT id_template FROM email_templates WHERE ten_template = 'BOOKING_CONFIRMATION'),
       'customer' || h.id_hoa_don || '@example.local',
       'Xác nhận đặt vé #' || h.id_hoa_don,
       '<p>Đơn #' || h.id_hoa_don || ' đã đặt thành công</p>',
