    );

-- Bảng 48: Bảng thông báo cho khách hàng
CREATE TABLE IF NOT EXISTS thong_bao
(
    id_thong_bao   SERIAL PRIMARY KEY,
    id_khach_hang  INT REFERENCES khach_hang (id_khach_hang) ON DELETE CASCADE, -- NULL = broadcast
    tieu_de        VARCHAR(200) NOT NULL,
    noi_dung       TEXT         NOT NULL,
    loai           VARCHAR(50)  CHECK (loai IN ('DAT_VE','THANH_TOAN','KHUYEN_MAI','HE_THONG')),
    kenh           VARCHAR(20)  CHECK (kenh IN ('IN_APP','EMAIL','SMS','PUSH')) DEFAULT 'IN_APP',
    trang_thai     VARCHAR(20)  CHECK (trang_thai IN ('PENDING','SENT','FAILED','READ')) DEFAULT 'PENDING',
    thoi_gian_gui  TIMESTAMP,
    thoi_gian_doc  TIMESTAMP,
    metadata       JSONB,
    ngay_tao       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Index cho bảng thong_bao
CREATE INDEX IF NOT EXISTS idx_thong_bao_khach_hang ON thong_bao (id_khach_hang);
CREATE INDEX IF NOT EXISTS idx_thong_bao_trang_thai ON thong_bao (trang_thai);

-- Seed một số thông báo mẫu (idempotent)
INSERT INTO thong_bao (id_khach_hang, tieu_de, noi_dung, loai, kenh, trang_thai, thoi_gian_gui, metadata)
SELECT kh.id_khach_hang,
       'Xác nhận đặt vé',
       'Đơn đặt vé của bạn đã được xác nhận. Hẹn gặp bạn tại rạp!',
       'DAT_VE',
       'IN_APP',
       'SENT',
       CURRENT_TIMESTAMP,
       jsonb_build_object('ma_dat_ve', h.ma_dat_ve, 'id_hoa_don', h.id_hoa_don)
FROM hoa_don h
         JOIN khach_hang kh ON kh.id_khach_hang = h.id_khach_hang
WHERE h.loai_hoa_don = 'Online'
  AND h.trang_thai_thanh_toan = 'HOAN_THANH'
  AND NOT EXISTS (SELECT 1
                  FROM thong_bao tb
                  WHERE tb.id_khach_hang = kh.id_khach_hang
                    AND tb.tieu_de = 'Xác nhận đặt vé')
LIMIT 5;


-- Bảng 49: Bảng quản lý giữ ghế (timeout đặt vé)
CREATE TABLE IF NOT EXISTS giu_ghe
(
    id_giu_ghe        SERIAL PRIMARY KEY,
    id_suat_chieu     INT NOT NULL REFERENCES suat_chieu (id_suat_chieu) ON DELETE CASCADE,
    id_ghe_ngoi       INT NOT NULL REFERENCES ghe_ngoi (id_ghe_ngoi) ON DELETE CASCADE,
    id_user_account   INT REFERENCES tai_khoan_nguoi_dung (id_user_account),
    hold_token        VARCHAR(100) UNIQUE,
    thoi_gian_bat_dau TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    thoi_gian_het_han TIMESTAMP NOT NULL,
    trang_thai        VARCHAR(20) CHECK (trang_thai IN ('DANG_GIU','HET_HAN','DA_MUA','HUY')) DEFAULT 'DANG_GIU'
);

-- Unique theo suat_chieu + ghe chỉ khi đang giữ
CREATE UNIQUE INDEX IF NOT EXISTS uq_giu_ghe_suat_ghe_danggiu
    ON giu_ghe (id_suat_chieu, id_ghe_ngoi)
    WHERE trang_thai = 'DANG_GIU';

-- Index hỗ trợ dọn timeout
CREATE INDEX IF NOT EXISTS idx_giu_ghe_het_han ON giu_ghe (thoi_gian_het_han);

-- Seed giữ ghế mẫu (idempotent, chỉ lấy ghế chưa bán/chưa đặt/chưa giữ)
WITH suat_ghe AS (
    SELECT s.id_suat_chieu,
           g.id_ghe_ngoi
    FROM suat_chieu s
    JOIN ghe_ngoi g ON g.id_phong_chieu = s.id_phong_chieu
    LEFT JOIN ve_phim v ON v.id_suat_chieu = s.id_suat_chieu AND v.id_ghe_ngoi = g.id_ghe_ngoi
    LEFT JOIN giu_ghe gg ON gg.id_suat_chieu = s.id_suat_chieu AND gg.id_ghe_ngoi = g.id_ghe_ngoi AND gg.trang_thai = 'DANG_GIU'
    WHERE v.id_ve_phim IS NULL AND gg.id_giu_ghe IS NULL
    ORDER BY s.id_suat_chieu, g.id_ghe_ngoi
    LIMIT 5
)
INSERT INTO giu_ghe (id_suat_chieu, id_ghe_ngoi, id_user_account, hold_token, thoi_gian_het_han, trang_thai)
SELECT sg.id_suat_chieu,
       sg.id_ghe_ngoi,
       (SELECT id_user_account FROM tai_khoan_nguoi_dung ORDER BY id_user_account LIMIT 1),
       'HOLD_' || sg.id_suat_chieu || '_' || sg.id_ghe_ngoi,
       CURRENT_TIMESTAMP + INTERVAL '15 minutes',
       'DANG_GIU'
FROM suat_ghe sg
WHERE NOT EXISTS (
    SELECT 1 FROM giu_ghe x WHERE x.id_suat_chieu = sg.id_suat_chieu AND x.id_ghe_ngoi = sg.id_ghe_ngoi AND x.trang_thai = 'DANG_GIU'
    );

--TẠO CÁC INDEX ĐỂ TỐI ƯU HIỆU SUẤT
-- =====================================================
-- Index cho bảng phim
CREATE INDEX IF NOT EXISTS idx_phim_trang_thai ON phim (trang_thai);
CREATE INDEX IF NOT EXISTS idx_phim_ngay_phat_hanh ON phim (ngay_phat_hanh);
CREATE INDEX IF NOT EXISTS idx_phim_tuoi_gioi_han ON phim (tuoi_gioi_han);
CREATE INDEX IF NOT EXISTS idx_phim_nam_san_xuat ON phim (nam_san_xuat);

-- Index cho bảng suat_chieu
CREATE INDEX IF NOT EXISTS idx_suat_chieu_ngay_gio ON suat_chieu (ngay_chieu, thoi_gian_bat_dau);
CREATE INDEX IF NOT EXISTS idx_suat_chieu_trang_thai ON suat_chieu (trang_thai);
CREATE INDEX IF NOT EXISTS idx_suat_chieu_phim ON suat_chieu (id_phim);

-- Index cho bảng ghe_ngoi
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_phong_trang_thai ON ghe_ngoi (id_phong_chieu, trang_thai);
CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_loai_gia ON ghe_ngoi (loai_ghe, gia_ghe_co_ban);

-- Index cho bảng hoa_don
CREATE INDEX IF NOT EXISTS idx_hoa_don_ngay_dat ON hoa_don (ngay_dat);
CREATE INDEX IF NOT EXISTS idx_hoa_don_trang_thai ON hoa_don (trang_thai);
CREATE INDEX IF NOT EXISTS idx_hoa_don_khach_hang ON hoa_don (id_khach_hang);

-- Index cho bảng ve_phim
CREATE INDEX IF NOT EXISTS idx_ve_phim_suat_chieu ON ve_phim (id_suat_chieu);
CREATE INDEX IF NOT EXISTS idx_ve_phim_trang_thai ON ve_phim (trang_thai);
CREATE INDEX IF NOT EXISTS idx_ve_phim_ma_ve ON ve_phim (ma_ve);

-- Index cho bảng khach_hang
CREATE INDEX IF NOT EXISTS idx_khach_hang_hang_thanh_vien ON khach_hang (hang_thanh_vien);
CREATE INDEX IF NOT EXISTS idx_khach_hang_diem_tich_luy ON khach_hang (diem_tich_luy);

-- Index cho bảng nhan_vien
CREATE INDEX IF NOT EXISTS idx_nhan_vien_chuc_vu ON nhan_vien (chuc_vu);
CREATE INDEX IF NOT EXISTS idx_nhan_vien_rap_chieu ON nhan_vien (id_rap_chieu);

-- Index cho bảng danh_gia_phim
CREATE INDEX IF NOT EXISTS idx_danh_gia_phim_diem ON danh_gia_phim (so_sao);
CREATE INDEX IF NOT EXISTS idx_danh_gia_phim_ngay ON danh_gia_phim (ngay_danh_gia);

-- Lịch sử vé theo khách hàng / lọc vé theo khách + suất chiếu
CREATE INDEX IF NOT EXISTS idx_ve_phim_khach_hang
    ON ve_phim (id_khach_hang);

CREATE INDEX IF NOT EXISTS idx_ve_phim_khach_hang_suat_chieu
    ON ve_phim (id_khach_hang, id_suat_chieu);

-- Kiểm tra/đếm vé theo ghế trong một suất chiếu
CREATE INDEX IF NOT EXISTS idx_ve_phim_suat_chieu_ghe
    ON ve_phim (id_suat_chieu, id_ghe_ngoi);

-- Tra cứu phân bổ voucher theo voucher
CREATE INDEX IF NOT EXISTS idx_khach_hang_voucher_voucher
    ON khach_hang_voucher (id_voucher);

-- Join nhanh thanh_toan theo hóa đơn và lọc trạng thái
CREATE INDEX IF NOT EXISTS idx_thanh_toan_hoa_don_trang_thai
    ON thanh_toan (id_hoa_don, trang_thai);

-- Lọc theo trạng thái thanh toán của hóa đơn (và theo ngày nếu cần báo cáo)
CREATE INDEX IF NOT EXISTS idx_hoa_don_trang_thai_thanh_toan
    ON hoa_don (trang_thai_thanh_toan);

CREATE INDEX IF NOT EXISTS idx_hoa_don_trang_thai_thanh_toan_ngay
    ON hoa_don (trang_thai_thanh_toan, ngay_dat);

-- Hộp thoại: truy vấn tin chưa đọc còn hoạt động theo phòng chat (partial index)
CREATE INDEX IF NOT EXISTS idx_tin_nhan_chat_unread_active
    ON tin_nhan_chat (ma_phong_chat, thoi_gian_tao)
    WHERE da_doc = false AND da_xoa = false;

--TẠO CÁC TRIGGER VÀ FUNCTION
-- =====================================================

-- Function tự động cập nhật ngay_cap_nhat
CREATE OR REPLACE FUNCTION cap_nhat_ngay_cap_nhat()
    RETURNS TRIGGER AS
$$
BEGIN
    NEW.ngay_cap_nhat = CURRENT_TIMESTAMP;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger cho các bảng có ngay_cap_nhat
CREATE TRIGGER trg_cap_nhat_ngay_phim
    BEFORE UPDATE
    ON phim
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_suat_chieu
    BEFORE UPDATE
    ON suat_chieu
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_ghe_ngoi
    BEFORE UPDATE
    ON ghe_ngoi
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_hoa_don
    BEFORE UPDATE
    ON hoa_don
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_ve_phim
    BEFORE UPDATE
    ON ve_phim
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_khach_hang
    BEFORE UPDATE
    ON khach_hang
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_nhan_vien
    BEFORE UPDATE
    ON nhan_vien
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_rap_chieu
    BEFORE UPDATE
    ON rap_chieu
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

-- Triggers cho hệ thống khuyến mãi
CREATE TRIGGER trg_cap_nhat_ngay_chien_dich
    BEFORE UPDATE
    ON chien_dich_khuyen_mai
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

CREATE TRIGGER trg_cap_nhat_ngay_khuyen_mai
    BEFORE UPDATE
    ON khuyen_mai
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

-- Trigger tự động cập nhật trạng thái chiến dịch
CREATE OR REPLACE FUNCTION cap_nhat_trang_thai_chien_dich()
    RETURNS TRIGGER AS
$$
BEGIN
    IF NEW.ngay_ket_thuc < CURRENT_DATE THEN
        NEW.trang_thai := 'HET_HAN';
END IF;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cap_nhat_trang_thai_chien_dich
    BEFORE INSERT OR UPDATE
    ON chien_dich_khuyen_mai
                         FOR EACH ROW
                         EXECUTE FUNCTION cap_nhat_trang_thai_chien_dich();

-- Trigger tự động cập nhật số lượng đã sử dụng
CREATE OR REPLACE FUNCTION cap_nhat_so_luong_su_dung()
    RETURNS TRIGGER AS
$$
BEGIN
UPDATE khuyen_mai
SET so_luong_da_su_dung = so_luong_da_su_dung + 1
WHERE id_khuyen_mai = NEW.id_khuyen_mai;

-- Kiểm tra nếu đã hết số lượng
UPDATE khuyen_mai
SET trang_thai = 'HET_HAN'
WHERE id_khuyen_mai = NEW.id_khuyen_mai
  AND so_luong_toi_da > 0
  AND so_luong_da_su_dung >= so_luong_toi_da;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cap_nhat_so_luong_su_dung
    AFTER INSERT
    ON lich_su_khuyen_mai
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_so_luong_su_dung();

-- Triggers cho hệ thống review nâng cao
CREATE TRIGGER trg_cap_nhat_ngay_ai_summaries
    BEFORE UPDATE
    ON ai_summaries
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

-- Triggers cho hệ thống điểm thưởng
CREATE TRIGGER trg_cap_nhat_ngay_quy_tac_diem_thuong
    BEFORE UPDATE
    ON quy_tac_diem_thuong
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_ngay_cap_nhat();

-- Function tự động tính điểm thưởng khi viết review
CREATE OR REPLACE FUNCTION tinh_diem_thuong_review()
    RETURNS TRIGGER AS
$$
DECLARE
diem_review INTEGER := 10; -- Điểm cơ bản cho review
    diem_video  INTEGER := 20; -- Điểm thêm cho review có video
    diem_thuong INTEGER := 0;
BEGIN
    -- Tính điểm cơ bản
    diem_thuong := diem_review;

    -- Thêm điểm nếu có video
    IF NEW.co_video = TRUE THEN
        diem_thuong := diem_thuong + diem_video;
END IF;

    -- Ghi lịch sử điểm thưởng
INSERT INTO lich_su_diem_thuong (id_khach_hang, loai_hanh_dong, so_diem, mo_ta, id_tham_chieu)
VALUES (NEW.id_khach_hang, 'VIET_REVIEW', diem_thuong,
        CASE
            WHEN NEW.co_video = TRUE THEN 'Viết review có video'
            ELSE 'Viết review'
            END,
        NEW.id_danh_gia);

-- Cập nhật điểm tích lũy cho khách hàng
UPDATE khach_hang
SET diem_tich_luy = diem_tich_luy + diem_thuong
WHERE id_khach_hang = NEW.id_khach_hang;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger tự động tính điểm khi viết review
CREATE TRIGGER trg_tinh_diem_thuong_review
    AFTER INSERT
    ON danh_gia_phim
    FOR EACH ROW
    EXECUTE FUNCTION tinh_diem_thuong_review();

-- Triggers cho hệ thống chat
-- Function tự động cập nhật thời gian tin nhắn cuối
CREATE OR REPLACE FUNCTION cap_nhat_thoi_gian_tin_nhan_cuoi()
    RETURNS TRIGGER AS
$$
BEGIN
UPDATE phong_chat
SET thoi_gian_tin_nhan_cuoi = NEW.thoi_gian_tao
WHERE ma_phong_chat = NEW.ma_phong_chat;
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cap_nhat_thoi_gian_tin_nhan_cuoi
    AFTER INSERT
    ON tin_nhan_chat
    FOR EACH ROW
    EXECUTE FUNCTION cap_nhat_thoi_gian_tin_nhan_cuoi();

-- Functions cho hệ thống chat
-- Function: Tạo phòng chat mới
CREATE OR REPLACE FUNCTION tao_phong_chat_moi(
    p_id_khach_hang INT,
    p_ten_phong_chat VARCHAR(200) DEFAULT NULL,
    p_nhan_dan TEXT DEFAULT NULL
) RETURNS VARCHAR(50) AS
$$
DECLARE
    v_ma_phong_chat  VARCHAR(50);
    v_ten_khach_hang VARCHAR(100);
BEGIN
    -- Lấy tên khách hàng
    SELECT ten_khach_hang
    INTO v_ten_khach_hang
FROM khach_hang
WHERE id_khach_hang = p_id_khach_hang;

IF v_ten_khach_hang IS NULL THEN
        RAISE EXCEPTION 'Không tìm thấy khách hàng với ID: %', p_id_khach_hang;
END IF;

    -- Tạo ma_phong_chat
    v_ma_phong_chat := 'PHONG_' || UPPER(SUBSTRING(gen_random_uuid()::text, 1, 8));

    -- Tạo phòng chat
INSERT INTO phong_chat (ma_phong_chat, ten_phong_chat, id_khach_hang, nhan_dan)
    VALUES (v_ma_phong_chat,
           COALESCE(p_ten_phong_chat, 'Hỗ trợ khách hàng - ' || v_ten_khach_hang),
           p_id_khach_hang,
            p_nhan_dan);

-- Gửi tin nhắn chào mừng
INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)
    VALUES (v_ma_phong_chat,
           'Hệ thống',
           'HE_THONG',
           'Chào mừng bạn đến với hệ thống hỗ trợ khách hàng! Chúng tôi sẽ phản hồi trong thời gian sớm nhất.',
           'HE_THONG',
            true);

RETURN v_ma_phong_chat;
END;
$$ LANGUAGE plpgsql;

-- Function: Gán nhân viên cho phòng chat
CREATE OR REPLACE FUNCTION gan_nhan_vien_cho_phong_chat(
    p_ma_phong_chat VARCHAR(50),
    p_id_nhan_vien INT
) RETURNS BOOLEAN AS
$$
DECLARE
v_ten_nhan_vien VARCHAR(100);
BEGIN
    -- Kiểm tra phòng chat tồn tại
    IF NOT EXISTS (SELECT 1 FROM phong_chat WHERE ma_phong_chat = p_ma_phong_chat) THEN
        RAISE EXCEPTION 'Không tìm thấy phòng chat: %', p_ma_phong_chat;
END IF;

    -- Lấy tên nhân viên
    SELECT ten_nhan_vien
    INTO v_ten_nhan_vien
FROM nhan_vien
WHERE id_nhan_vien = p_id_nhan_vien;

IF v_ten_nhan_vien IS NULL THEN
        RAISE EXCEPTION 'Không tìm thấy nhân viên với ID: %', p_id_nhan_vien;
END IF;

    -- Cập nhật nhân viên cho phòng chat
UPDATE phong_chat
SET id_nhan_vien = p_id_nhan_vien
WHERE ma_phong_chat = p_ma_phong_chat;

-- Gửi tin nhắn thông báo
INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)
    VALUES (p_ma_phong_chat,
           'Hệ thống',
           'HE_THONG',
           'Nhân viên ' || v_ten_nhan_vien || ' đã được phân công hỗ trợ bạn.',
           'HE_THONG',
            true);

RETURN true;
END;
$$ LANGUAGE plpgsql;

-- Function: Đóng phòng chat
CREATE OR REPLACE FUNCTION dong_phong_chat(p_ma_phong_chat VARCHAR(50)) RETURNS BOOLEAN AS
$$
BEGIN
    -- Kiểm tra phòng chat tồn tại
    IF NOT EXISTS (SELECT 1 FROM phong_chat WHERE ma_phong_chat = p_ma_phong_chat) THEN
        RAISE EXCEPTION 'Không tìm thấy phòng chat: %', p_ma_phong_chat;
END IF;

    -- Cập nhật trạng thái phòng chat
UPDATE phong_chat
    SET trang_thai     = 'DONG',
        thoi_gian_dong = CURRENT_TIMESTAMP,
        dang_hoat_dong = false
WHERE ma_phong_chat = p_ma_phong_chat;

-- Gửi tin nhắn thông báo đóng phòng
INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)
    VALUES (p_ma_phong_chat,
           'Hệ thống',
           'HE_THONG',
           'Phòng chat đã được đóng. Cảm ơn bạn đã sử dụng dịch vụ hỗ trợ!',
           'HE_THONG',
            true);

RETURN true;
END;
$$ LANGUAGE plpgsql;

-- Function tự động tạo mã vé
CREATE OR REPLACE FUNCTION tao_ma_ve()
    RETURNS TRIGGER AS
$$
BEGIN
    NEW.ma_ve := 'VE' || LPAD(NEW.id_ve_phim::TEXT, 8, '0');
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger cho bảng ve_phim
CREATE TRIGGER trg_tao_ma_ve
    BEFORE INSERT
    ON ve_phim
    FOR EACH ROW
    EXECUTE FUNCTION tao_ma_ve();


-- (Đã lược bỏ các UPDATE mẫu tinh chỉnh phim/suất chiếu/ghế để tối giản file)


-- TẠO CÁC VIEW HỮU ÍCH
-- =====================================================

-- View: Danh sách hóa đơn đã thanh toán kèm khách hàng
CREATE OR REPLACE VIEW v_danh_sach_hoa_don_thanh_toan AS
SELECT h.id_hoa_don,
       h.ten_hoa_don,
       h.tong_tien,
       h.tien_giam,
       h.ngay_dat,
       k.ten_khach_hang,
       h.trang_thai
FROM hoa_don h
         JOIN khach_hang k ON h.id_khach_hang = k.id_khach_hang
WHERE h.trang_thai = 'DA_THANH_TOAN';

-- View: Lịch chiếu hôm nay
CREATE OR REPLACE VIEW v_lich_chieu_hom_nay AS
SELECT s.id_suat_chieu,
       s.ten_suat_chieu,
       p.ten_phim,
       s.ngay_chieu,
       s.thoi_gian_bat_dau,
       pc.ten_phong_chieu,
       r.ten_rap_chieu
FROM suat_chieu s
         JOIN phim p ON s.id_phim = p.id_phim
         JOIN phong_chieu pc ON s.id_phong_chieu = pc.id_phong_chieu
         JOIN rap_chieu r ON pc.id_rap_chieu = r.id_rap_chieu
WHERE s.ngay_chieu = CURRENT_DATE;

-- View: Thống kê doanh thu theo ngày
CREATE OR REPLACE VIEW v_doanh_thu_theo_ngay AS
SELECT h.ngay_dat,
       COUNT(h.id_hoa_don)            as so_hoa_don,
       SUM(h.tong_tien)               as tong_doanh_thu,
       SUM(h.tien_giam)               as tong_tien_giam,
       SUM(h.tong_tien - h.tien_giam) as doanh_thu_thuc
FROM hoa_don h
WHERE h.trang_thai = 'DA_THANH_TOAN'
GROUP BY h.ngay_dat
ORDER BY h.ngay_dat DESC;

-- View: Top phim được xem nhiều nhất
CREATE OR REPLACE VIEW v_top_phim_pho_bien AS
SELECT p.id_phim,
       p.ten_phim,
       p.luot_xem,
       p.danh_gia_trung_binh,
       COUNT(v.id_ve_phim) as so_ve_da_ban
FROM phim p
         LEFT JOIN ve_phim v ON p.id_phim = v.id_phim
GROUP BY p.id_phim, p.ten_phim, p.luot_xem, p.danh_gia_trung_binh
ORDER BY p.luot_xem DESC, p.danh_gia_trung_binh DESC;

-- Views cho hệ thống khuyến mãi
-- View khuyến mãi đang hoạt động
CREATE OR REPLACE VIEW v_khuyen_mai_dang_hoat_dong AS
SELECT km.id_khuyen_mai,
    km.loai_khuyen_mai,
    km.gia_tri,
    km.mo_ta,
    cdk.ten_chien_dich,
    cdk.ngay_bat_dau,
    cdk.ngay_ket_thuc,
    km.so_luong_toi_da,
    km.so_luong_da_su_dung,
    (km.so_luong_toi_da - km.so_luong_da_su_dung) as so_luong_con_lai
FROM khuyen_mai km
         JOIN chien_dich_khuyen_mai cdk ON km.id_chien_dich = cdk.id_chien_dich
WHERE cdk.trang_thai = 'HOAT_DONG'
  AND km.trang_thai = 'HOAT_DONG'
  AND CURRENT_DATE BETWEEN cdk.ngay_bat_dau AND cdk.ngay_ket_thuc;

-- View thống kê khuyến mãi
CREATE OR REPLACE VIEW v_thong_ke_khuyen_mai AS
SELECT cdk.ten_chien_dich,
       COUNT(km.id_khuyen_mai)          as so_khuyen_mai,
       SUM(ls.so_tien_giam)             as tong_tien_giam,
       COUNT(ls.id_lich_su)             as so_lan_su_dung,
    COUNT(DISTINCT ls.id_khach_hang) as so_khach_hang_su_dung
FROM chien_dich_khuyen_mai cdk
         LEFT JOIN khuyen_mai km ON cdk.id_chien_dich = km.id_chien_dich
         LEFT JOIN lich_su_khuyen_mai ls ON km.id_khuyen_mai = ls.id_khuyen_mai
GROUP BY cdk.id_chien_dich, cdk.ten_chien_dich;

-- Đảm bảo các cột mở rộng tồn tại trước khi tạo các VIEW review nâng cao
ALTER TABLE danh_gia_phim
    ADD COLUMN IF NOT EXISTS phuong_thuc_mua VARCHAR(50),
    ADD COLUMN IF NOT EXISTS diem_cong       INTEGER DEFAULT 0,
    ADD COLUMN IF NOT EXISTS co_video        BOOLEAN DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS so_luot_xem     INTEGER DEFAULT 0;

ALTER TABLE khach_hang
    ADD COLUMN IF NOT EXISTS so_danh_gia INTEGER DEFAULT 0;

-- Views cho hệ thống review nâng cao
-- View: Review với media và tags
CREATE OR REPLACE VIEW v_review_chi_tiet AS
SELECT dg.id_danh_gia,
    dg.id_phim,
    p.ten_phim,
    dg.id_khach_hang,
    kh.ten_khach_hang,
    dg.so_sao,
    dg.tieu_de_danh_gia,
    dg.noi_dung_danh_gia,
    dg.phuong_thuc_mua,
    dg.diem_cong,
    dg.co_video,
    dg.so_luot_xem,
    dg.ngay_danh_gia,
    -- Media
       COUNT(DISTINCT rm.id)                                            as so_luong_media,
    COUNT(DISTINCT CASE WHEN rm.loai_media = 'IMAGE' THEN rm.id END) as so_anh,
    COUNT(DISTINCT CASE WHEN rm.loai_media = 'VIDEO' THEN rm.id END) as so_video,
    -- Tags
       string_agg(DISTINCT rt.ten_tag, ', ')                            as danh_sach_tags,
    -- Badges của khách hàng
       string_agg(DISTINCT ub.ten_badge, ', ')                          as danh_sach_badges
FROM danh_gia_phim dg
         JOIN phim p ON dg.id_phim = p.id_phim
         JOIN khach_hang kh ON dg.id_khach_hang = kh.id_khach_hang
         LEFT JOIN review_media rm ON dg.id_danh_gia = rm.id_danh_gia
         LEFT JOIN review_tags rt ON dg.id_danh_gia = rt.id_danh_gia
         LEFT JOIN user_badges ub ON kh.id_khach_hang = ub.id_khach_hang
WHERE dg.trang_thai = 'HOAT_DONG'
GROUP BY dg.id_danh_gia, dg.id_phim, p.ten_phim, dg.id_khach_hang, kh.ten_khach_hang,
         dg.so_sao, dg.tieu_de_danh_gia, dg.noi_dung_danh_gia, dg.phuong_thuc_mua,
         dg.diem_cong, dg.co_video, dg.so_luot_xem, dg.ngay_danh_gia;

-- View: Thống kê review theo phim
CREATE OR REPLACE VIEW v_thong_ke_review_phim AS
SELECT p.id_phim,
    p.ten_phim,
       COUNT(dg.id_danh_gia)                          as tong_so_review,
       AVG(dg.so_sao)                                 as diem_trung_binh,
    COUNT(CASE WHEN dg.co_video = true THEN 1 END) as so_review_co_video,
       SUM(dg.so_luot_xem)                            as tong_luot_xem_review,
       SUM(dg.diem_cong)                              as tong_diem_cong,
       COUNT(DISTINCT dg.id_khach_hang)               as so_khach_hang_danh_gia,
    -- AI Summary
    ai.noi_dung_tong_hop,
    ai.danh_gia_tong_the,
    ai.danh_gia_thong_diep,
    ai.danh_gia_kich_ban,
    ai.danh_gia_cam_xuc,
       ai.so_luot_thich                               as ai_luot_thich,
       ai.so_luot_khong_thich                         as ai_luot_khong_thich
FROM phim p
         LEFT JOIN danh_gia_phim dg ON p.id_phim = dg.id_phim AND dg.trang_thai = 'HOAT_DONG'
         LEFT JOIN ai_summaries ai ON p.id_phim = ai.id_phim AND ai.trang_thai = 'HOAT_DONG'
GROUP BY p.id_phim, p.ten_phim, ai.noi_dung_tong_hop, ai.danh_gia_tong_the,
         ai.danh_gia_thong_diep, ai.danh_gia_kich_ban, ai.danh_gia_cam_xuc,
         ai.so_luot_thich, ai.so_luot_khong_thich;

-- View: Top khách hàng có nhiều review
CREATE OR REPLACE VIEW v_top_khach_hang_review AS
SELECT kh.id_khach_hang,
    kh.ten_khach_hang,
    kh.email,
    kh.so_danh_gia,
    kh.diem_tich_luy,
    kh.hang_thanh_vien,
       COUNT(dg.id_danh_gia)                   as so_review_da_viet,
       AVG(dg.so_sao)                          as diem_trung_binh_danh_gia,
       SUM(dg.diem_cong)                       as tong_diem_cong,
       SUM(dg.so_luot_xem)                     as tong_luot_xem_review,
       COUNT(DISTINCT ub.id)                   as so_badge,
    string_agg(DISTINCT ub.ten_badge, ', ') as danh_sach_badges
FROM khach_hang kh
         LEFT JOIN danh_gia_phim dg ON kh.id_khach_hang = dg.id_khach_hang AND dg.trang_thai = 'HOAT_DONG'
         LEFT JOIN user_badges ub ON kh.id_khach_hang = ub.id_khach_hang
WHERE kh.trang_thai = 'HOAT_DONG'
GROUP BY kh.id_khach_hang, kh.ten_khach_hang, kh.email, kh.so_danh_gia,
         kh.diem_tich_luy, kh.hang_thanh_vien
ORDER BY so_review_da_viet DESC, tong_diem_cong DESC;

-- Views cho hệ thống điểm thưởng
-- View: Thống kê điểm thưởng theo khách hàng
CREATE OR REPLACE VIEW v_thong_ke_diem_thuong AS
SELECT kh.id_khach_hang,
    kh.ten_khach_hang,
    kh.email,
    kh.diem_tich_luy,
    kh.hang_thanh_vien,
       COUNT(ls.id)                                                  as tong_so_hanh_dong,
       SUM(ls.so_diem)                                               as tong_diem_nhan,
    COUNT(CASE WHEN ls.loai_hanh_dong = 'VIET_REVIEW' THEN 1 END) as so_review,
       COUNT(CASE WHEN ls.loai_hanh_dong = 'XEM_PHIM' THEN 1 END)    as so_lan_xem_phim,
       COUNT(CASE WHEN ls.loai_hanh_dong = 'MUA_COMBO' THEN 1 END)   as so_lan_mua_combo,
       MAX(ls.ngay_nhan)                                             as lan_cuoi_nhan_diem
FROM khach_hang kh
         LEFT JOIN lich_su_diem_thuong ls ON kh.id_khach_hang = ls.id_khach_hang
WHERE kh.trang_thai = 'HOAT_DONG'
GROUP BY kh.id_khach_hang, kh.ten_khach_hang, kh.email, kh.diem_tich_luy, kh.hang_thanh_vien
ORDER BY tong_diem_nhan DESC;

-- View: Top khách hàng theo hạng thành viên
CREATE OR REPLACE VIEW v_top_khach_hang_theo_hang AS
SELECT hang_thanh_vien,
       COUNT(*)           as so_khach_hang,
    AVG(diem_tich_luy) as diem_trung_binh,
    MIN(diem_tich_luy) as diem_thap_nhat,
    MAX(diem_tich_luy) as diem_cao_nhat,
    SUM(diem_tich_luy) as tong_diem
FROM khach_hang
WHERE trang_thai = 'HOAT_DONG'
GROUP BY hang_thanh_vien
ORDER BY CASE hang_thanh_vien
        WHEN 'KIM_CUONG' THEN 1
        WHEN 'VANG' THEN 2
        WHEN 'BAC' THEN 3
        WHEN 'DONG' THEN 4
        END;

-- View: Lịch sử điểm thưởng chi tiết
CREATE OR REPLACE VIEW v_lich_su_diem_thuong_chi_tiet AS
SELECT ls.id,
    ls.id_khach_hang,
    kh.ten_khach_hang,
    ls.loai_hanh_dong,
    ls.so_diem,
    ls.mo_ta,
    ls.id_tham_chieu,
    ls.ngay_nhan,
    qt.ten_quy_tac,
    qt.dieu_kien
FROM lich_su_diem_thuong ls
         JOIN khach_hang kh ON ls.id_khach_hang = kh.id_khach_hang
         LEFT JOIN quy_tac_diem_thuong qt ON ls.id_quy_tac = qt.id
ORDER BY ls.ngay_nhan DESC;

-- Views cho hệ thống chat
-- View: Danh sách phòng chat với thông tin chi tiết
CREATE OR REPLACE VIEW v_chi_tiet_phong_chat AS
SELECT pc.id_phong_chat,
    pc.ma_phong_chat,
    pc.ten_phong_chat,
    pc.loai_phong_chat,
    pc.id_khach_hang,
       kh.ten_khach_hang          as ten_khach_hang,
       kh.email                   as email_khach_hang,
    pc.id_nhan_vien,
       nv.ten_nhan_vien           as ten_nhan_vien,
    pc.dang_hoat_dong,
    pc.thoi_gian_tin_nhan_cuoi,
    pc.thoi_gian_tao,
    pc.thoi_gian_dong,
    pc.trang_thai,
    pc.muc_do_uu_tien,
    pc.nhan_dan,
       (SELECT COUNT(*)
        FROM tin_nhan_chat tnc
        WHERE tnc.ma_phong_chat = pc.ma_phong_chat
          AND tnc.da_doc = false
          AND tnc.da_xoa = false) as so_tin_nhan_chua_doc,
       (SELECT tnc.noi_dung_tin_nhan
        FROM tin_nhan_chat tnc
        WHERE tnc.ma_phong_chat = pc.ma_phong_chat
          AND tnc.da_xoa = false
        ORDER BY tnc.thoi_gian_tao DESC
        LIMIT 1)                  as tin_nhan_cuoi
FROM phong_chat pc
    LEFT JOIN khach_hang kh ON pc.id_khach_hang = kh.id_khach_hang
    LEFT JOIN nhan_vien nv ON pc.id_nhan_vien = nv.id_nhan_vien
ORDER BY pc.thoi_gian_tin_nhan_cuoi DESC;

-- View: Thống kê chat theo ngày
CREATE OR REPLACE VIEW v_thong_ke_chat_theo_ngay AS
SELECT DATE(tnc.thoi_gian_tao)                                                     as ngay,
       COUNT(*)                                                                    as tong_tin_nhan,
       COUNT(DISTINCT pc.ma_phong_chat)                                            as so_phong_chat,
       COUNT(DISTINCT tnc.id_nguoi_gui)                                            as so_nguoi_dung,
       COUNT(CASE WHEN tnc.loai_nguoi_gui = 'KHACH_HANG' THEN 1 END)               as tin_nhan_khach_hang,
    COUNT(CASE WHEN tnc.loai_nguoi_gui IN ('NHAN_VIEN', 'QUAN_TRI') THEN 1 END) as tin_nhan_nhan_vien,
       COUNT(CASE WHEN tnc.loai_nguoi_gui = 'HE_THONG' THEN 1 END)                 as tin_nhan_he_thong
FROM tin_nhan_chat tnc
    JOIN phong_chat pc ON tnc.ma_phong_chat = pc.ma_phong_chat
WHERE tnc.da_xoa = false
GROUP BY DATE(tnc.thoi_gian_tao)
ORDER BY ngay DESC;

-- View: Phòng chat chưa có nhân viên
CREATE OR REPLACE VIEW v_phong_chat_chua_co_nhan_vien AS
SELECT pc.*,
    kh.ten_khach_hang,
    kh.email,
       (SELECT COUNT(*)
        FROM tin_nhan_chat tnc
        WHERE tnc.ma_phong_chat = pc.ma_phong_chat AND tnc.da_xoa = false) as so_tin_nhan,
       (SELECT tnc.thoi_gian_tao
        FROM tin_nhan_chat tnc
        WHERE tnc.ma_phong_chat = pc.ma_phong_chat
          AND tnc.da_xoa = false
        ORDER BY tnc.thoi_gian_tao DESC
        LIMIT 1)                                                           as hoat_dong_cuoi
FROM phong_chat pc
    JOIN khach_hang kh ON pc.id_khach_hang = kh.id_khach_hang
WHERE pc.id_nhan_vien IS NULL
  AND pc.trang_thai = 'MO'
  AND pc.dang_hoat_dong = true
ORDER BY pc.thoi_gian_tao ASC;

