-- Chuẩn hóa giá trị hạng thành viên để khớp với trigger (DONG/BAC/VANG/KIM_CUONG)
ALTER TABLE khach_hang
    DROP CONSTRAINT IF EXISTS khach_hang_hang_thanh_vien_check;

ALTER TABLE khach_hang
    ALTER COLUMN hang_thanh_vien SET DEFAULT 'DONG';

ALTER TABLE khach_hang
    ADD CONSTRAINT khach_hang_hang_thanh_vien_check
        CHECK (hang_thanh_vien IN ('DONG', 'BAC', 'VANG', 'KIM_CUONG'));

-- Nếu có dữ liệu sẵn, chuẩn hóa về bộ giá trị mới
UPDATE khach_hang
SET hang_thanh_vien = CASE UPPER(REPLACE(hang_thanh_vien, ' ', '_'))
                          WHEN 'KIM_CUONG' THEN 'KIM_CUONG'
                          WHEN 'VANG' THEN 'VANG'
                          WHEN 'BAC' THEN 'BAC'
                          ELSE 'DONG'
    END;

