-- Trigger: Khi hóa đơn được thanh toán thành công, đánh dấu voucher của khách là 'DA_SU_DUNG'
CREATE OR REPLACE FUNCTION cap_nhat_trang_thai_khv_sau_thanh_toan()
    RETURNS TRIGGER AS
$$
BEGIN
    IF NEW.id_voucher IS NOT NULL AND
       (NEW.trang_thai = 'DA_THANH_TOAN' OR NEW.trang_thai_thanh_toan = 'HOAN_THANH') THEN
        UPDATE khach_hang_voucher
        SET trang_thai = 'DA_SU_DUNG'
        WHERE id_khach_hang = NEW.id_khach_hang
          AND id_voucher = NEW.id_voucher
          AND trang_thai <> 'DA_SU_DUNG';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_cap_nhat_khv_sau_thanh_toan ON hoa_don;
CREATE TRIGGER trg_cap_nhat_khv_sau_thanh_toan
    AFTER INSERT OR UPDATE
    ON hoa_don
    FOR EACH ROW
EXECUTE FUNCTION cap_nhat_trang_thai_khv_sau_thanh_toan();

