-- 4. Lịch sử sử dụng khuyến mãi (map bằng email khách và vé đầu tiên của khách)
-- Chỉ chèn khi có vé: dùng INSERT ... SELECT để tránh NULL id_ve_phim
WITH ds(email, id_khuyen_mai, so_tien_giam, ve_offset) AS (VALUES
                                                                  ('nguyenvanan@gmail.com', 1, 18000.00, 0),
                                                                  ('nguyenvanan@gmail.com', 1, 18000.00, 1),
                                                                  ('phamquocdat@gmail.com', 2, 15000.00, 0),
                                                                  ('hoangvanson@gmail.com', 3, 13500.00, 0),
                                                                  ('lethihanh@gmail.com', 3, 12000.00, 0),
                                                                  ('phammanhtuan@gmail.com', 4, 25000.00, 0),
                                                                  ('tranthidung@gmail.com', 1, 19000.00, 0),
                                                                  ('nguyenhainam@gmail.com', 2, 15000.00, 0),
                                                                  ('vuthihoa@gmail.com', 3, 15000.00, 0),
                                                                  ('nguyenvanan@gmail.com', 1, 36000.00, 0),
                                                                  ('vuthihoa@gmail.com', 1, 12000.00, 1),
                                                                  ('ngobichphuong@gmail.com', 2, 12000.00, 0),
                                                                  ('lyvanhung@gmail.com', 3, 15000.00, 0),
                                                                  ('tothitrang@gmail.com', 1, 15000.00, 0),
                                                                  ('trinhvankhoa@gmail.com', 2, 10000.00, 0)
                                                                  ),
     ve_khach AS (SELECT kh.id_khach_hang,
                         kh.email,
                         v.id_ve_phim,
                         ROW_NUMBER() OVER (PARTITION BY kh.id_khach_hang ORDER BY v.id_ve_phim) - 1 AS rn
                  FROM khach_hang kh
                           JOIN ve_phim v ON v.id_khach_hang = kh.id_khach_hang)
INSERT
INTO lich_su_khuyen_mai (id_khuyen_mai, id_ve_phim, id_khach_hang, so_tien_giam)
SELECT ds.id_khuyen_mai, vk.id_ve_phim, vk.id_khach_hang, ds.so_tien_giam
FROM ds
         JOIN ve_khach vk
              ON vk.email = ds.email
                 AND vk.rn = ds.ve_offset;

-- Insert dữ liệu cho hệ thống review nâng cao
-- 1. Review Tags
-- Map tag theo email khách + review gần nhất để không phụ thuộc id_danh_gia cứng
WITH review_map AS (SELECT dg.id_danh_gia,
                           dg.id_khach_hang,
                           kh.email,
                           ROW_NUMBER() OVER (PARTITION BY kh.email ORDER BY dg.id_danh_gia) AS rn
                    FROM danh_gia_phim dg
                             JOIN khach_hang kh ON kh.id_khach_hang = dg.id_khach_hang)
