-- Bổ sung thêm review để đủ tối thiểu 15 (idempotent)
INSERT INTO danh_gia_phim (id_phim, id_khach_hang, so_sao, noi_dung_danh_gia, trang_thai,
                           tieu_de_danh_gia,
                           co_anh_kem_theo, so_luot_thich, so_luot_phan_hoi, da_xem_phim, ngay_xem_phim,
                           rap_chieu, loai_ve, gia_ve)
SELECT x.id_phim, x.id_khach_hang, 5, 'Review mẫu ' || x.rn, 'HOAT_DONG', 'Tiêu đề review ' || x.rn,
       true, 5 + (x.rn % 10), 1 + (x.rn % 5), true, CURRENT_DATE - (x.rn || ' days')::interval,
       'Dev Cinemas Xuân Thủy', CASE WHEN (x.rn % 2)=0 THEN '2D' ELSE '3D' END,
       CASE WHEN (x.rn % 2)=0 THEN 60000.00 ELSE 80000.00 END
FROM (
  SELECT gs AS rn,
         ((gs - 1) % 15) + 1 AS id_phim,
         18 + ((gs - 1) % 15) AS id_khach_hang
  FROM generate_series(1,15) AS gs
) x
WHERE NOT EXISTS (
  SELECT 1 FROM danh_gia_phim dg WHERE dg.id_phim = x.id_phim AND dg.id_khach_hang = x.id_khach_hang
);


