-- Insert cho bảng GheNgoi
WITH room_capacity AS (SELECT pc.id_phong_chieu,
                              pc.dien_tich_phong,
                              GREATEST(40, LEAST(200, FLOOR(pc.dien_tich_phong / 1.6)))::int AS so_ghe
                       FROM phong_chieu pc),
     grid AS (SELECT id_phong_chieu,
                     so_ghe,
                     CEIL(SQRT(so_ghe * 0.75))::int                AS so_hang,
                     CEIL(so_ghe / CEIL(SQRT(so_ghe * 0.75)))::int AS so_cot
              FROM room_capacity),
     seats AS (SELECT g.id_phong_chieu,
                      r.r,
                      c.c,
                      chr(64 + r.r) AS hang_ghe, -- 1->A, 2->B...
                      c.c::text     AS so_ghe,
                      CASE
                          WHEN c.c BETWEEN CEIL(g.so_cot * 0.30) AND FLOOR(g.so_cot * 0.70) THEN 'VIP'
                          WHEN r.r >= g.so_hang - 1 THEN 'GheDoi'
                          ELSE 'Thuong'
                          END       AS loai_ghe,
                      CASE
                          WHEN c.c BETWEEN CEIL(g.so_cot * 0.30) AND FLOOR(g.so_cot * 0.70) THEN 80000.00
                          WHEN r.r >= g.so_hang - 1 THEN 120000.00
                          ELSE 50000.00
                          END       AS gia_ghe_co_ban
               FROM grid g
                        CROSS JOIN LATERAL generate_series(1, g.so_hang) AS r(r)
                        CROSS JOIN LATERAL generate_series(1, g.so_cot) AS c(c))
INSERT
INTO ghe_ngoi (hang_ghe, so_ghe, id_phong_chieu, trang_thai, loai_ghe, gia_ghe_co_ban)
SELECT hang_ghe, so_ghe, id_phong_chieu, 'CON_TRONG', loai_ghe, gia_ghe_co_ban
FROM seats
ON CONFLICT (id_phong_chieu, hang_ghe, so_ghe) DO NOTHING;


--Suất chiếu
WITH capacity AS (SELECT id_phong_chieu,
                         COUNT(*)                                    AS tong_so_ghe,
                         ROW_NUMBER() OVER (ORDER BY id_phong_chieu) AS rn
                  FROM ghe_ngoi
                  GROUP BY id_phong_chieu),
     sc_rows(rn, ten, day_offset, start_t, end_t, id_phim) AS (VALUES (1, 'Suất 1: Nhà Bà Nữ', 0, '09:00', '11:00', 1),
