INSERT
INTO suat_chieu (ten_suat_chieu, ngay_chieu, thoi_gian_bat_dau, thoi_gian_ket_thuc, trang_thai, id_phim, id_phong_chieu,
                 so_ghe_con_trong, tong_so_ghe)
SELECT rdef.ten,
       CURRENT_DATE + rdef.day_offset,
       rdef.start_t::time,
       rdef.end_t::time,
       'DA_LEN_LICH',
       rdef.id_phim,
       c.id_phong_chieu,
       c.tong_so_ghe,
       c.tong_so_ghe
FROM sc_rows rdef
         JOIN capacity c ON c.rn = rdef.rn;

