-- Cập nhật bảng hoa_don để thêm mã giao dịch và mã đặt vé
ALTER TABLE hoa_don
    ADD COLUMN IF NOT EXISTS ma_giao_dich     VARCHAR(50) UNIQUE,
    ADD COLUMN IF NOT EXISTS ma_dat_ve        VARCHAR(50) UNIQUE,
    ADD CONSTRAINT hoa_don_owner_check CHECK (
    (loai_hoa_don = 'Online' AND id_khach_hang IS NOT NULL) OR
    (loai_hoa_don = 'Tai_Quay' AND id_nhan_vien IS NOT NULL)
    ),
    ADD COLUMN IF NOT EXISTS trang_thai_email VARCHAR(20) DEFAULT 'CHUA_GUI',
    ADD COLUMN IF NOT EXISTS ngay_gui_email   TIMESTAMP;

-- Sửa dữ liệu hoa đơn Online thiếu id_khach_hang bằng cách map theo số điện thoại
UPDATE hoa_don h
SET id_khach_hang = kh.id_khach_hang
FROM khach_hang kh
WHERE h.loai_hoa_don = 'Online'
  AND h.id_khach_hang IS NULL
  AND kh.so_dien_thoai = h.so_dien_thoai;

-- Với hóa đơn tại quầy thiếu id_nhan_vien, gán một thu ngân mặc định
UPDATE hoa_don h
SET id_nhan_vien = (SELECT nv.id_nhan_vien
                    FROM nhan_vien nv
                    WHERE nv.chuc_vu = 'THU_NGAN'
                    ORDER BY nv.id_nhan_vien
                    LIMIT 1)
WHERE h.loai_hoa_don = 'Tai_Quay'
  AND h.id_nhan_vien IS NULL;

-- Tạo khách ẩn danh nếu chưa có, dùng để gán cho hóa đơn Online thiếu chủ sở hữu
INSERT INTO khach_hang (ten_khach_hang, email, so_dien_thoai, ngay_sinh, gioi_tinh, trang_thai)
SELECT 'Khách Ẩn Danh', 'anonymous+hoa_don@local', '0000000000', CURRENT_DATE - INTERVAL '20 years', 'Nam', 'HOAT_DONG'
WHERE NOT EXISTS (SELECT 1 FROM khach_hang WHERE email = 'anonymous+hoa_don@local');

-- Gán khách ẩn danh cho mọi hóa đơn Online còn thiếu id_khach_hang
UPDATE hoa_don
SET id_khach_hang = (SELECT id_khach_hang FROM khach_hang WHERE email = 'anonymous+hoa_don@local')
WHERE loai_hoa_don = 'Online'
  AND id_khach_hang IS NULL;

DO
$$
    BEGIN
        IF NOT EXISTS (SELECT 1
                       FROM information_schema.table_constraints
                       WHERE table_name = 'hoa_don'
                         AND constraint_name = 'hoa_don_owner_check') THEN
            ALTER TABLE hoa_don
                ADD CONSTRAINT hoa_don_owner_check CHECK (
                    (loai_hoa_don = 'Online' AND id_khach_hang IS NOT NULL) OR
                    (loai_hoa_don = 'Tai_Quay' AND id_nhan_vien IS NOT NULL)
                    );
        END IF;
    END
$$;

