-- GIN index for full-text search on movie names (Vietnamese)
-- Nếu instance không có cấu hình 'vietnamese', fallback về 'simple'
DO
$$
    BEGIN
        IF EXISTS (SELECT 1 FROM pg_ts_config WHERE cfgname = 'vietnamese') THEN
            EXECUTE 'CREATE INDEX IF NOT EXISTS idx_phim_ten_phim ON phim USING gin(to_tsvector(''vietnamese'', ten_phim))';
        ELSE
            EXECUTE 'CREATE INDEX IF NOT EXISTS idx_phim_ten_phim ON phim USING gin(to_tsvector(''simple'', ten_phim))';
        END IF;
    END
$$ LANGUAGE plpgsql;

