-- View: Lịch sử điểm thưởng chi tiết

CREATE OR REPLACE VIEW v_lich_su_diem_thuong_chi_tiet AS

SELECT

    ls.id,

    ls.id_khach_hang,

    kh.ten_khach_hang,

    ls.loai_hanh_dong,

    ls.so_diem,

    ls.mo_ta,

    ls.id_tham_chieu,

    ls.ngay_nhan,

    qt.ten_quy_tac,

    qt.dieu_kien

FROM lich_su_diem_thuong ls

         JOIN khach_hang kh ON ls.id_khach_hang = kh.id_khach_hang

         LEFT JOIN quy_tac_diem_thuong qt ON ls.id_quy_tac = qt.id

ORDER BY ls.ngay_nhan DESC;



-- Views cho hệ thống chat

-- View: Danh sách phòng chat với thông tin chi tiết

CREATE OR REPLACE VIEW v_chi_tiet_phong_chat AS

SELECT

    pc.id_phong_chat,

    pc.ma_phong_chat,

    pc.ten_phong_chat,

    pc.loai_phong_chat,

    pc.id_khach_hang,

    kh.ten_khach_hang as ten_khach_hang,

    kh.email as email_khach_hang,

    pc.id_nhan_vien,

    nv.ten_nhan_vien as ten_nhan_vien,

    pc.dang_hoat_dong,

    pc.thoi_gian_tin_nhan_cuoi,

    pc.thoi_gian_tao,

    pc.thoi_gian_dong,

    pc.trang_thai,

    pc.muc_do_uu_tien,

    pc.nhan_dan,

    (SELECT COUNT(*) FROM tin_nhan_chat tnc WHERE tnc.ma_phong_chat = pc.ma_phong_chat AND tnc.da_doc = false AND tnc.da_xoa = false) as so_tin_nhan_chua_doc,

    (SELECT tnc.noi_dung_tin_nhan FROM tin_nhan_chat tnc WHERE tnc.ma_phong_chat = pc.ma_phong_chat AND tnc.da_xoa = false ORDER BY tnc.thoi_gian_tao DESC LIMIT 1) as tin_nhan_cuoi

FROM phong_chat pc

    LEFT JOIN khach_hang kh ON pc.id_khach_hang = kh.id_khach_hang

    LEFT JOIN nhan_vien nv ON pc.id_nhan_vien = nv.id_nhan_vien

ORDER BY pc.thoi_gian_tin_nhan_cuoi DESC;



-- View: Thống kê chat theo ngày

CREATE OR REPLACE VIEW v_thong_ke_chat_theo_ngay AS

SELECT

    DATE(tnc.thoi_gian_tao) as ngay,

    COUNT(*) as tong_tin_nhan,

    COUNT(DISTINCT pc.ma_phong_chat) as so_phong_chat,

    COUNT(DISTINCT tnc.id_nguoi_gui) as so_nguoi_dung,

    COUNT(CASE WHEN tnc.loai_nguoi_gui = 'KHACH_HANG' THEN 1 END) as tin_nhan_khach_hang,

    COUNT(CASE WHEN tnc.loai_nguoi_gui IN ('NHAN_VIEN', 'QUAN_TRI') THEN 1 END) as tin_nhan_nhan_vien,

    COUNT(CASE WHEN tnc.loai_nguoi_gui = 'HE_THONG' THEN 1 END) as tin_nhan_he_thong

FROM tin_nhan_chat tnc

    JOIN phong_chat pc ON tnc.ma_phong_chat = pc.ma_phong_chat

WHERE tnc.da_xoa = false

GROUP BY DATE(tnc.thoi_gian_tao)

ORDER BY ngay DESC;



-- View: Phòng chat chưa có nhân viên

CREATE OR REPLACE VIEW v_phong_chat_chua_co_nhan_vien AS

SELECT

    pc.*,

    kh.ten_khach_hang,

    kh.email,

    (SELECT COUNT(*) FROM tin_nhan_chat tnc WHERE tnc.ma_phong_chat = pc.ma_phong_chat AND tnc.da_xoa = false) as so_tin_nhan,

    (SELECT tnc.thoi_gian_tao FROM tin_nhan_chat tnc WHERE tnc.ma_phong_chat = pc.ma_phong_chat AND tnc.da_xoa = false ORDER BY tnc.thoi_gian_tao DESC LIMIT 1) as hoat_dong_cuoi

FROM phong_chat pc

    JOIN khach_hang kh ON pc.id_khach_hang = kh.id_khach_hang

WHERE pc.id_nhan_vien IS NULL AND pc.trang_thai = 'MO' AND pc.dang_hoat_dong = true

ORDER BY pc.thoi_gian_tao ASC;





