-- PERFORMANCE OPTIMIZATION INDEXES

-- =====================================================

-- Additional indexes for better query performance



-- 1. Booking System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_hoa_don_khach_hang_ngay

    ON hoa_don(id_khach_hang, ngay_dat);



CREATE INDEX IF NOT EXISTS idx_hoa_don_so_dien_thoai

    ON hoa_don(so_dien_thoai);



-- 2. Showtime System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_suat_chieu_phim_ngay

    ON suat_chieu(id_phim, ngay_chieu);



CREATE INDEX IF NOT EXISTS idx_suat_chieu_phong_ngay

    ON suat_chieu(id_phong_chieu, ngay_chieu);



CREATE INDEX IF NOT EXISTS idx_suat_chieu_trang_thai

    ON suat_chieu(trang_thai);



-- 3. Movie System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_phim_ngay_phat_hanh

    ON phim(ngay_phat_hanh);



-- GIN index for full-text search on movie names (Vietnamese)

CREATE INDEX IF NOT EXISTS idx_phim_ten_phim

    ON phim USING gin(to_tsvector('vietnamese', ten_phim));



-- 4. Seat System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_phong_chieu

    ON ghe_ngoi(id_phong_chieu);



CREATE INDEX IF NOT EXISTS idx_ghe_ngoi_trang_thai

    ON ghe_ngoi(trang_thai);



-- 5. User System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_tai_khoan_ten_dang_nhap

    ON tai_khoan_nguoi_dung(ten_dang_nhap);



CREATE INDEX IF NOT EXISTS idx_khach_hang_so_dien_thoai

    ON khach_hang(so_dien_thoai);



-- 6. Review System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_danh_gia_phim_phim

    ON danh_gia_phim(id_phim);



CREATE INDEX IF NOT EXISTS idx_danh_gia_phim_khach_hang

    ON danh_gia_phim(id_khach_hang);



-- 7. Promotion System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_khuyen_mai_trang_thai

    ON khuyen_mai(trang_thai);



CREATE INDEX IF NOT EXISTS idx_chien_dich_khuyen_mai_trang_thai

    ON chien_dich_khuyen_mai(trang_thai);



-- 8. Chat System Performance Indexes

CREATE INDEX IF NOT EXISTS idx_phong_chat_khach_hang_trang_thai

    ON phong_chat(id_khach_hang, trang_thai);



CREATE INDEX IF NOT EXISTS idx_tin_nhan_chat_phong_thoi_gian

    ON tin_nhan_chat(ma_phong_chat, thoi_gian_tao);



