-- FIX USER ACCOUNT QUERIES - Minimal SQL Script

-- =====================================================

-- Script này chỉ sửa những vấn đề cần thiết cho UserAccountRepository



-- 1. Đảm bảo tất cả user account có avatar_url

UPDATE tai_khoan_nguoi_dung

SET avatar_url = '/images/avatars/default.png'

WHERE avatar_url IS NULL OR avatar_url = '';



-- 2. Cập nhật thông tin user account (không có ngay_tao và ngay_cap_nhat trong schema)



-- 4. Tạo indexes để tối ưu performance cho queries

-- CREATE INDEX IF NOT EXISTS idx_tai_khoan_ngay_tao ON tai_khoan_nguoi_dung(ngay_tao); -- Cột không tồn tại

CREATE INDEX IF NOT EXISTS idx_tai_khoan_vai_tro ON tai_khoan_nguoi_dung(id_vai_tro);

CREATE INDEX IF NOT EXISTS idx_tai_khoan_trang_thai ON tai_khoan_nguoi_dung(trang_thai);

CREATE INDEX IF NOT EXISTS idx_hoa_don_khach_hang ON hoa_don(id_khach_hang);

CREATE INDEX IF NOT EXISTS idx_hoa_don_ngay_tao ON hoa_don(ngay_tao);



-- 5. Tạo view để dễ dàng query thống kê

CREATE OR REPLACE VIEW user_statistics_view AS

SELECT

    ua.id_user_account,

    ua.ten_dang_nhap,

    ua.email,

    r.ten_vai_tro,

    ua.trang_thai,

    ua.avatar_url,

    COUNT(hd.id_hoa_don) as so_hoa_don,

    COALESCE(SUM(hd.tong_tien), 0) as tong_tien_da_mua

FROM tai_khoan_nguoi_dung ua

         LEFT JOIN vai_tro r ON ua.id_vai_tro = r.id_role

         LEFT JOIN khach_hang kh ON ua.id_khach_hang = kh.id_khach_hang

         LEFT JOIN hoa_don hd ON kh.id_khach_hang = hd.id_khach_hang

GROUP BY ua.id_user_account, ua.ten_dang_nhap, ua.email, r.ten_vai_tro, ua.trang_thai, ua.avatar_url;



