-- Index cho bảng checkin_ve

CREATE INDEX IF NOT EXISTS idx_checkin_ve_thoi_gian ON checkin_ve (thoi_gian_checkin);

CREATE INDEX IF NOT EXISTS idx_checkin_ve_trang_thai ON checkin_ve (trang_thai);



-- Function kiểm tra thời gian checkin hợp lệ

CREATE OR REPLACE FUNCTION kiem_tra_thoi_gian_checkin()

    RETURNS TRIGGER AS

$$

DECLARE

thoi_gian_chieu TIMESTAMP;

    thoi_gian_checkin_hop_le TIMESTAMP;

    thoi_gian_checkin_toi_thieu TIMESTAMP;

BEGIN

    -- Lấy thời gian chiếu từ suất chiếu

SELECT s.ngay_chieu + s.thoi_gian_bat_dau INTO thoi_gian_chieu

FROM suat_chieu s

         JOIN ve_phim v ON s.id_suat_chieu = v.id_suat_chieu

WHERE v.id_ve_phim = NEW.id_ve_phim;



-- Thời gian checkin hợp lệ: trước giờ chiếu 1 tiếng

thoi_gian_checkin_hop_le := thoi_gian_chieu - INTERVAL '1 hour';



    -- Thời gian checkin tối thiểu: trước giờ chiếu 30 phút

    thoi_gian_checkin_toi_thieu := thoi_gian_chieu - INTERVAL '30 minutes';



    -- Kiểm tra thời gian checkin

    IF NEW.thoi_gian_checkin > thoi_gian_chieu THEN

        RAISE EXCEPTION 'Không thể checkin sau giờ chiếu phim';

END IF;



    IF NEW.thoi_gian_checkin < thoi_gian_checkin_hop_le THEN

        RAISE EXCEPTION 'Chỉ được checkin trước giờ chiếu 1 tiếng';

END IF;



    IF NEW.thoi_gian_checkin < thoi_gian_checkin_toi_thieu THEN

        RAISE WARNING 'Checkin quá sớm, nên checkin trong khoảng 30 phút trước giờ chiếu';

END IF;



RETURN NEW;

END;

$$ LANGUAGE plpgsql;



-- Trigger kiểm tra thời gian checkin

CREATE TRIGGER trg_kiem_tra_thoi_gian_checkin

    BEFORE INSERT OR UPDATE OF thoi_gian_checkin

                     ON checkin_ve

                         FOR EACH ROW

                         EXECUTE FUNCTION kiem_tra_thoi_gian_checkin();



-- Function tự động cập nhật trạng thái vé sau khi checkin

CREATE OR REPLACE FUNCTION cap_nhat_trang_thai_ve_sau_checkin()

    RETURNS TRIGGER AS

$$

BEGIN

    -- Cập nhật trạng thái vé thành 'DA_BAN' sau khi checkin

UPDATE ve_phim

SET trang_thai = 'DA_BAN',

    ngay_cap_nhat = CURRENT_TIMESTAMP

WHERE id_ve_phim = NEW.id_ve_phim;



RETURN NEW;

END;

$$ LANGUAGE plpgsql;



-- Trigger cập nhật trạng thái vé sau checkin

CREATE TRIGGER trg_cap_nhat_ve_sau_checkin

    AFTER INSERT

    ON checkin_ve

    FOR EACH ROW

    EXECUTE FUNCTION cap_nhat_trang_thai_ve_sau_checkin();



-- Function kiểm tra vé đã được thanh toán chưa trước khi checkin

CREATE OR REPLACE FUNCTION kiem_tra_ve_da_thanh_toan()

    RETURNS TRIGGER AS

$$

DECLARE

trang_thai_ve VARCHAR(20);

BEGIN

    -- Lấy trạng thái vé

SELECT trang_thai INTO trang_thai_ve

FROM ve_phim

WHERE id_ve_phim = NEW.id_ve_phim;



-- Kiểm tra vé đã được thanh toán chưa

IF trang_thai_ve != 'DA_BAN' THEN

        RAISE EXCEPTION 'Chỉ có thể checkin vé đã thanh toán';

END IF;



RETURN NEW;

END;

$$ LANGUAGE plpgsql;



-- Trigger kiểm tra vé đã thanh toán

CREATE TRIGGER trg_kiem_tra_ve_da_thanh_toan

    BEFORE INSERT

    ON checkin_ve

    FOR EACH ROW

    EXECUTE FUNCTION kiem_tra_ve_da_thanh_toan();



-- View: Danh sách vé đã checkin hôm nay

CREATE OR REPLACE VIEW v_ve_da_checkin_hom_nay AS

SELECT

    cv.id_checkin,

    cv.thoi_gian_checkin,

    v.ma_ve,

    p.ten_phim,

    s.ngay_chieu,

    s.thoi_gian_bat_dau,

    kh.ten_khach_hang,

    nv.ten_nhan_vien as nhan_vien_checkin,

    pc.ten_phong_chieu,

    r.ten_rap_chieu

FROM checkin_ve cv

         JOIN ve_phim v ON cv.id_ve_phim = v.id_ve_phim

         JOIN suat_chieu s ON v.id_suat_chieu = s.id_suat_chieu

         JOIN phim p ON v.id_phim = p.id_phim

         JOIN khach_hang kh ON v.id_khach_hang = kh.id_khach_hang

         JOIN phong_chieu pc ON v.id_phong_chieu = pc.id_phong_chieu

         JOIN rap_chieu r ON pc.id_rap_chieu = r.id_rap_chieu

         LEFT JOIN nhan_vien nv ON cv.id_nhan_vien_checkin = nv.id_nhan_vien

WHERE DATE(cv.thoi_gian_checkin) = CURRENT_DATE

ORDER BY cv.thoi_gian_checkin DESC;



-- View: Thống kê checkin theo ngày

CREATE OR REPLACE VIEW v_thong_ke_checkin_theo_ngay AS

SELECT

    DATE(cv.thoi_gian_checkin) as ngay_checkin,

    COUNT(*) as so_ve_da_checkin,

    COUNT(DISTINCT v.id_khach_hang) as so_khach_hang,

    COUNT(DISTINCT v.id_phim) as so_phim,

    COUNT(DISTINCT r.id_rap_chieu) as so_rap

FROM checkin_ve cv

    JOIN ve_phim v ON cv.id_ve_phim = v.id_ve_phim

    JOIN phong_chieu pc ON v.id_phong_chieu = pc.id_phong_chieu

    JOIN rap_chieu r ON pc.id_rap_chieu = r.id_rap_chieu

GROUP BY DATE(cv.thoi_gian_checkin)

ORDER BY ngay_checkin DESC;



