SET avatar_url = '/images/avatars/default.png'

WHERE avatar_url IS NULL OR avatar_url = '';



-- 2. Cập nhật thông tin user account (không có ngay_tao và ngay_cap_nhat trong schema)



-- 4. Tạo indexes để tối ưu performance cho queries

-- CREATE INDEX IF NOT EXISTS idx_tai_khoan_ngay_tao ON tai_khoan_nguoi_dung(ngay_tao); -- Cột không tồn tại

CREATE INDEX IF NOT EXISTS idx_tai_khoan_vai_tro ON tai_khoan_nguoi_dung(id_vai_tro);

