-- Insert dữ liệu cho hệ thống chat

-- Tạo phòng chat cho tất cả khách hàng có sẵn

INSERT INTO phong_chat (ma_phong_chat, ten_phong_chat, loai_phong_chat, id_khach_hang, trang_thai, muc_do_uu_tien, nhan_dan)

SELECT

    'PHONG_' || LPAD(k.id_khach_hang::text, 8, '0') as ma_phong_chat,

    'Hỗ trợ khách hàng - ' || COALESCE(k.ten_khach_hang, 'Khách hàng ' || k.id_khach_hang) as ten_phong_chat,

    'HO_TRO_KHACH_HANG' as loai_phong_chat,

    k.id_khach_hang as id_khach_hang,

    CASE

        WHEN k.id_khach_hang % 3 = 0 THEN 'DONG'

        WHEN k.id_khach_hang % 3 = 1 THEN 'MO'

        ELSE 'CHO_XU_LY'

        END as trang_thai,

    CASE

        WHEN k.id_khach_hang % 4 = 0 THEN 'KHAN_CAP'

        WHEN k.id_khach_hang % 4 = 1 THEN 'CAO'

        WHEN k.id_khach_hang % 4 = 2 THEN 'BINH_THUONG'

        ELSE 'THAP'

        END as muc_do_uu_tien,

    CASE

        WHEN k.id_khach_hang % 5 = 0 THEN 'thanh_toan'

        WHEN k.id_khach_hang % 5 = 1 THEN 'ky_thuat'

        WHEN k.id_khach_hang % 5 = 2 THEN 'dat_ve'

        WHEN k.id_khach_hang % 5 = 3 THEN 'hoa_don'

        ELSE 'chung'

        END as nhan_dan

FROM khach_hang k

WHERE k.id_khach_hang IS NOT NULL

    ON CONFLICT (ma_phong_chat) DO NOTHING;



-- Tạo tin nhắn mẫu cho một số phòng chat (5 phòng đầu tiên)

-- Tin nhắn chào mừng cho tất cả phòng chat

INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)

SELECT

    pc.ma_phong_chat,

    'Hệ thống',

    'HE_THONG',

    'Chào mừng bạn đến với hệ thống hỗ trợ khách hàng! Chúng tôi sẽ phản hồi trong thời gian sớm nhất.',

    'HE_THONG',

    true

FROM phong_chat pc

WHERE pc.loai_phong_chat = 'HO_TRO_KHACH_HANG'

    LIMIT 5;



-- Tin nhắn từ khách hàng cho 3 phòng đầu tiên

INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)

SELECT

    pc.ma_phong_chat,

    'Khách hàng',

    'KHACH_HANG',

    CASE

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) = 1 THEN 'Xin chào, tôi muốn hỏi về cách đặt vé phim online. Có thể hướng dẫn tôi không?'

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) = 2 THEN 'Tôi gặp lỗi khi thanh toán online. Hệ thống báo "Giao dịch thất bại" nhưng tiền vẫn bị trừ.'

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) = 3 THEN 'Tôi muốn hủy vé đã đặt cho suất chiếu ngày mai. Có được không?'

        ELSE 'Tôi cần hỗ trợ về dịch vụ.'

        END,

    'VAN_BAN',

    CASE

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) <= 2 THEN true

        ELSE false

        END

FROM phong_chat pc

WHERE pc.loai_phong_chat = 'HO_TRO_KHACH_HANG'

    LIMIT 3;



-- Tin nhắn phản hồi từ nhân viên cho 2 phòng đầu tiên (sử dụng tên nhân viên có chức vụ ONLINE_SUPPORT)

INSERT INTO tin_nhan_chat (ma_phong_chat, ten_nguoi_gui, loai_nguoi_gui, noi_dung_tin_nhan, loai_tin_nhan, da_doc)

SELECT

    pc.ma_phong_chat,

    CASE

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) = 1 THEN 'Lê Thị Yến'

        ELSE 'Võ Thị Hòa'

        END,

    'NHAN_VIEN',

    CASE

        WHEN ROW_NUMBER() OVER (ORDER BY pc.ma_phong_chat) = 1 THEN 'Chào bạn! Tôi sẽ hướng dẫn bạn cách đặt vé phim online. Bạn có thể làm theo các bước sau: 1. Chọn rạp chiếu, 2. Chọn phim và suất chiếu, 3. Chọn ghế, 4. Thanh toán.'

        ELSE 'Chào bạn! Tôi rất tiếc về sự cố này. Để tôi kiểm tra thông tin giao dịch của bạn. Bạn có thể cung cấp mã giao dịch không?'

        END,

    'VAN_BAN',

    false

FROM phong_chat pc

WHERE pc.loai_phong_chat = 'HO_TRO_KHACH_HANG'

    LIMIT 2;



-- Cập nhật thời gian tin nhắn cuối

UPDATE phong_chat SET thoi_gian_tin_nhan_cuoi = (

    SELECT MAX(thoi_gian_tao) FROM tin_nhan_chat WHERE ma_phong_chat = phong_chat.ma_phong_chat

);



