-- 2. Insert phòng chiếu cho từng rạp chiếu hiện có

-- Sử dụng subquery để lấy ID thực tế từ bảng rap_chieu



-- Rạp 1

INSERT INTO phong_chieu (ten_phong_chieu, dien_tich_phong, trang_thai, id_rap_chieu)

SELECT

    'Phòng ' || generate_series(1, 10),

    120.0 + (generate_series(1, 10) * 5.0),

    'HOAT_DONG',

    (SELECT id_rap_chieu FROM rap_chieu ORDER BY id_rap_chieu LIMIT 1 OFFSET 0);



-- Rạp 2

INSERT INTO phong_chieu (ten_phong_chieu, dien_tich_phong, trang_thai, id_rap_chieu)

SELECT

    'Phòng ' || generate_series(1, 10),

    120.0 + (generate_series(1, 10) * 5.0),

    'HOAT_DONG',

