-- 3. AI Summaries

INSERT INTO ai_summaries (id_phim, noi_dung_tong_hop, danh_gia_tong_the, danh_gia_thong_diep, danh_gia_kich_ban, danh_gia_cam_xuc, so_luot_thich, so_luot_khong_thich) VALUES

                                                                                                                                                                           (1, 'Khán giả đánh giá bộ phim này là một tuyệt phẩm với thông điệp sâu sắc về chiến tranh và hòa bình. Kịch bản được đánh giá cao với 9.9/10 điểm. 95.2% khán giả đánh giá tích cực.', 9.9, 8.7, 8.0, 9.5, 2400, 120),

                                                                                                                                                                           (2, 'Phim hành động kịch tính với nhiều tình tiết bất ngờ. Diễn xuất xuất sắc và kỹ xảo đỉnh cao. 88.5% khán giả hài lòng với bộ phim này.', 8.5, 7.8, 9.2, 8.0, 1800, 200),

                                                                                                                                                                           (3, 'Bộ phim lịch sử cảm động về Hà Nội thời kháng chiến. Thông điệp ý nghĩa và diễn xuất chân thực. 92.3% khán giả đánh giá tích cực.', 9.2, 9.5, 8.8, 9.0, 2100, 150),

                                                                                                                                                                           (4, 'Bản live-action của phim hoạt hình nổi tiếng. Hình ảnh đẹp mắt và âm nhạc hay. Phù hợp cho gia đình. 85.7% khán giả hài lòng.', 8.7, 8.0, 8.5, 8.9, 1600, 180),

                                                                                                                                                                           (5, 'Câu chuyện về Joker - phản anh hùng. Diễn xuất xuất sắc của Joaquin Phoenix. 90.1% khán giả đánh giá cao.', 9.1, 9.3, 8.9, 9.2, 2200, 100);



