-- 5. Tạo view để dễ dàng query thống kê

CREATE OR REPLACE VIEW user_statistics_view AS

SELECT

    ua.id_user_account,

    ua.ten_dang_nhap,

    ua.email,

    r.ten_vai_tro,

    ua.trang_thai,

    ua.avatar_url,

    COUNT(hd.id_hoa_don) as so_hoa_don,

    COALESCE(SUM(hd.tong_tien), 0) as tong_tien_da_mua

FROM tai_khoan_nguoi_dung ua

         LEFT JOIN vai_tro r ON ua.id_vai_tro = r.id_role

         LEFT JOIN khach_hang kh ON ua.id_khach_hang = kh.id_khach_hang

         LEFT JOIN hoa_don hd ON kh.id_khach_hang = hd.id_khach_hang

GROUP BY ua.id_user_account, ua.ten_dang_nhap, ua.email, r.ten_vai_tro, ua.trang_thai, ua.avatar_url;



