    ADD COLUMN IF NOT EXISTS ma_dat_ve VARCHAR(50) UNIQUE,

    ADD CONSTRAINT hoa_don_owner_check CHECK (

    (loai_hoa_don = 'Online' AND id_khach_hang IS NOT NULL) OR

    (loai_hoa_don = 'Tai_Quay' AND id_nhan_vien IS NOT NULL)

    ),

    ADD COLUMN IF NOT EXISTS trang_thai_email VARCHAR(20) DEFAULT 'CHUA_GUI',

    ADD COLUMN IF NOT EXISTS ngay_gui_email TIMESTAMP;



-- Cập nhật bảng danh_gia_phim để thêm cột mới

ALTER TABLE danh_gia_phim

    ADD COLUMN IF NOT EXISTS phuong_thuc_mua VARCHAR(50),

    ADD COLUMN IF NOT EXISTS diem_cong INTEGER DEFAULT 0,

    ADD COLUMN IF NOT EXISTS co_video BOOLEAN DEFAULT FALSE,

    ADD COLUMN IF NOT EXISTS so_luot_xem INTEGER DEFAULT 0;



-- Cập nhật bảng khach_hang để thêm cột mới (chỉ thêm so_danh_gia vì diem_tich_luy đã có)

ALTER TABLE khach_hang

    ADD COLUMN IF NOT EXISTS so_danh_gia INTEGER DEFAULT 0;



-- Tạo index cho mã giao dịch và mã đặt vé

CREATE INDEX IF NOT EXISTS idx_hoa_don_ma_giao_dich ON hoa_don (ma_giao_dich);

CREATE INDEX IF NOT EXISTS idx_hoa_don_ma_dat_ve ON hoa_don (ma_dat_ve);



-- Index cho email history

CREATE INDEX IF NOT EXISTS idx_email_history_hoa_don ON email_history (hoa_don_id);

CREATE INDEX IF NOT EXISTS idx_email_history_trang_thai ON email_history (trang_thai);

CREATE INDEX IF NOT EXISTS idx_email_history_ngay_gui ON email_history (ngay_gui);



-- Trigger để cập nhật ngay_cap_nhat

CREATE OR REPLACE FUNCTION update_email_templates_updated_at()

RETURNS TRIGGER AS $$

BEGIN

    NEW.ngay_cap_nhat = CURRENT_TIMESTAMP;

RETURN NEW;

END;

$$ LANGUAGE plpgsql;



CREATE TRIGGER trg_update_email_templates_updated_at

    BEFORE UPDATE ON email_templates

    FOR EACH ROW

    EXECUTE FUNCTION update_email_templates_updated_at();





DO $$

BEGIN

        IF NOT EXISTS (

            SELECT 1

            FROM information_schema.table_constraints

            WHERE constraint_name = 'fk_khach_hang_avatar'

              AND table_name = 'khach_hang'

              AND constraint_type = 'FOREIGN KEY'

        ) THEN

ALTER TABLE khach_hang

    ADD CONSTRAINT fk_khach_hang_avatar

        FOREIGN KEY (id_avatar) REFERENCES avatars(id) ON DELETE SET NULL;

END IF;

END $$;



--ép unique với giá trị khác NULL

CREATE UNIQUE INDEX IF NOT EXISTS uq_tknd_email_not_null

    ON tai_khoan_nguoi_dung (email) WHERE email IS NOT NULL;





UPDATE hinh_anh

SET url = CASE

              WHEN loai_hinh_anh = 'POSTER' THEN '/uploads/posters/' || ten_hinh_anh

              WHEN loai_hinh_anh = 'BANNER' THEN '/uploads/banners/' || ten_hinh_anh

              ELSE '/uploads/' || lower(loai_hinh_anh) || '/' || ten_hinh_anh

    END

WHERE url LIKE '/images/%' OR url LIKE '%/';



