-- Thêm các cột mới cho soft delete
ALTER TABLE phim
    ADD COLUMN da_xoa BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ngay_xoa TIMESTAMP;

-- Tạo index để tối ưu hóa truy vấn
CREATE INDEX idx_phim_da_xoa ON phim(da_xoa);
