-- Cập nhật dữ liệu hiện tại (đảm bảo tất cả phim hiện tại chưa bị xóa)
UPDATE phim SET da_xoa = FALSE WHERE da_xoa IS NULL;

-- Thêm comment cho các cột mới
COMMENT ON COLUMN phim.da_xoa IS 'Trạng thái xóa mềm: TRUE = đã xóa, FALSE = chưa xóa';
COMMENT ON COLUMN phim.ngay_xoa IS 'Thời gian xóa mềm phim';

-- Tạo view để dễ dàng truy vấn phim chưa xóa
CREATE OR REPLACE VIEW v_phim_active AS
SELECT * FROM phim WHERE da_xoa = FALSE;

-- Tạo function để xóa mềm phim
CREATE OR REPLACE FUNCTION soft_delete_phim(phim_id INTEGER)
    RETURNS BOOLEAN AS $$
BEGIN
    UPDATE phim
    SET da_xoa = TRUE,
        ngay_xoa = CURRENT_TIMESTAMP,
        ngay_cap_nhat = CURRENT_TIMESTAMP
    WHERE id_phim = phim_id AND da_xoa = FALSE;

    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;

-- Tạo function để khôi phục phim
CREATE OR REPLACE FUNCTION restore_phim(phim_id INTEGER)
    RETURNS BOOLEAN AS $$
BEGIN
    UPDATE phim
    SET da_xoa = FALSE,
        ngay_xoa = NULL,
        ngay_cap_nhat = CURRENT_TIMESTAMP
    WHERE id_phim = phim_id AND da_xoa = TRUE;

    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;

-- Tạo trigger để tự động cập nhật ngay_cap_nhat
CREATE OR REPLACE FUNCTION update_ngay_cap_nhat()
    RETURNS TRIGGER AS $$
BEGIN
    NEW.ngay_cap_nhat = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_update_ngay_cap_nhat
    BEFORE UPDATE ON phim
    FOR EACH ROW
EXECUTE FUNCTION update_ngay_cap_nhat();

-- Tạo trigger để tự động set ngay_tao khi tạo mới
CREATE OR REPLACE FUNCTION set_ngay_tao()
    RETURNS TRIGGER AS $$
BEGIN
    IF NEW.ngay_tao IS NULL THEN
        NEW.ngay_tao = CURRENT_TIMESTAMP;
    END IF;
    IF NEW.ngay_cap_nhat IS NULL THEN
        NEW.ngay_cap_nhat = CURRENT_TIMESTAMP;
    END IF;
    IF NEW.da_xoa IS NULL THEN
        NEW.da_xoa = FALSE;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_set_ngay_tao
    BEFORE INSERT ON phim
    FOR EACH ROW
EXECUTE FUNCTION set_ngay_tao();

