-- Script tạo suất chiếu cho 7 ngày liên tiếp
-- Từ 25/09/2025 đến 01/10/2025

-- Tạo suất chiếu cho 7 ngày liên tiếp
WITH date_series AS (
    SELECT generate_series(
                   '2025-09-25'::DATE,
                   '2025-10-01'::DATE,
                   '1 day'::INTERVAL
           )::DATE AS ngay_chieu
),
     time_slots AS (
         SELECT unnest(ARRAY['08:00:00', '10:00:00', '12:00:00', '14:00:00', '16:00:00', '18:00:00', '20:00:00', '20:30:00', '21:00:00', '21:30:00'])::TIME AS thoi_gian_bat_dau
     ),
     movie_rooms AS (
         SELECT
             p.id_phim,
             p.ten_phim,
             p.thoi_luong,
             pc.id_phong_chieu,
             pc.ten_phong_chieu
         FROM phim p
                  CROSS JOIN phong_chieu pc
         WHERE p.trang_thai IN ('DANG_CHIEU', 'SAP_CHIEU')
           AND pc.id_rap_chieu = 2 -- Dev Cinemas Tây Sơn
     )
INSERT INTO suat_chieu (
    ten_suat_chieu,
    ngay_chieu,
    thoi_gian_bat_dau,
    thoi_gian_ket_thuc,
    trang_thai,
    id_phim,
    id_phong_chieu,
    so_ghe_con_trong,
    tong_so_ghe,
    ngay_tao,
    ngay_cap_nhat
)
SELECT
    mr.ten_phim || ' - ' || ds.ngay_chieu || ' - ' || ts.thoi_gian_bat_dau AS ten_suat_chieu,
    ds.ngay_chieu,
    ts.thoi_gian_bat_dau,
    CASE
        WHEN (ts.thoi_gian_bat_dau + (mr.thoi_luong || ' minutes')::INTERVAL)::TIME < ts.thoi_gian_bat_dau
            THEN (ts.thoi_gian_bat_dau + (mr.thoi_luong || ' minutes')::INTERVAL + INTERVAL '1 day')::TIME
        ELSE (ts.thoi_gian_bat_dau + (mr.thoi_luong || ' minutes')::INTERVAL)::TIME
        END AS thoi_gian_ket_thuc,
    'DANG_CHIEU' AS trang_thai,
    mr.id_phim,
    mr.id_phong_chieu,
    FLOOR(RANDOM() * 20) + 30 AS so_ghe_con_trong, -- Random 30-50
    FLOOR(RANDOM() * 20) + 50 AS tong_so_ghe, -- Random 50-70
    NOW() AS ngay_tao,
    NOW() AS ngay_cap_nhat
FROM date_series ds
         CROSS JOIN time_slots ts
         CROSS JOIN movie_rooms mr;

-- Hiển thị thống kê
SELECT
    'TONG KET 7 NGAY' AS loai,
    COUNT(*) AS so_suat_chieu,
    COUNT(DISTINCT ngay_chieu) AS so_ngay,
    COUNT(DISTINCT id_phim) AS so_phim,
    MIN(ngay_chieu) AS ngay_bat_dau,
    MAX(ngay_chieu) AS ngay_ket_thuc
FROM suat_chieu
WHERE ngay_chieu >= '2025-09-25'
  AND ngay_chieu <= '2025-10-01'

UNION ALL

SELECT
    p.ten_phim AS loai,
    COUNT(sc.id_suat_chieu) AS so_suat_chieu,
    COUNT(DISTINCT sc.ngay_chieu) AS so_ngay,
    1 AS so_phim,
    MIN(sc.ngay_chieu) AS ngay_bat_dau,
    MAX(sc.ngay_chieu) AS ngay_ket_thuc
FROM phim p
         LEFT JOIN suat_chieu sc ON p.id_phim = sc.id_phim
WHERE sc.ngay_chieu >= '2025-09-25'
  AND sc.ngay_chieu <= '2025-10-01'
GROUP BY p.id_phim, p.ten_phim
ORDER BY so_suat_chieu DESC;


-- ========================================
-- HỆ THỐNG TỰ ĐỘNG TẠO SUẤT CHIẾU cho 1 ngày
-- ========================================

-- 1. FUNCTION TỰ ĐỘNG TẠO SUẤT CHIẾU CHO 1 NGÀY
CREATE OR REPLACE FUNCTION generate_showtimes_for_date(
    target_date DATE,
    cinema_id INTEGER DEFAULT NULL
)
    RETURNS TABLE(
                     message TEXT,
                     created_count INTEGER,
                     date_created DATE
                 ) AS $$
DECLARE
    created_count INTEGER := 0;
    movie_record RECORD;
    room_record RECORD;
    time_slot TIME;
    time_slots TIME[] := ARRAY[
        '08:00:00'::TIME, '08:30:00'::TIME, '09:00:00'::TIME, '09:30:00'::TIME,
        '10:00:00'::TIME, '10:30:00'::TIME, '11:00:00'::TIME, '11:30:00'::TIME,
        '12:00:00'::TIME, '12:30:00'::TIME, '13:00:00'::TIME, '13:30:00'::TIME,
        '14:00:00'::TIME, '14:30:00'::TIME, '15:00:00'::TIME, '15:30:00'::TIME,
        '16:00:00'::TIME, '16:30:00'::TIME, '17:00:00'::TIME, '17:30:00'::TIME,
        '18:00:00'::TIME, '18:30:00'::TIME, '19:00:00'::TIME, '19:30:00'::TIME,
        '20:00:00'::TIME, '20:30:00'::TIME, '21:00:00'::TIME, '21:30:00'::TIME,
        '22:00:00'::TIME
        ];
    slot_index INTEGER;
    end_time TIME;
    i INTEGER;
BEGIN
    -- Xóa suất chiếu cũ cho ngày này
    DELETE FROM suat_chieu WHERE ngay_chieu = target_date;

    -- Lấy danh sách phim đang chiếu
    FOR movie_record IN
        SELECT id_phim, ten_phim, thoi_luong
        FROM phim
        WHERE trang_thai IN ('DANG_CHIEU', 'SAP_CHIEU')
        ORDER BY RANDOM() -- Random để đa dạng
        LOOP
            -- Lấy danh sách phòng chiếu
            FOR room_record IN
                SELECT id_phong_chieu, ten_phong_chieu
                FROM phong_chieu
                WHERE id_rap_chieu = cinema_id
                ORDER BY id_phong_chieu
                LOOP
                    -- Tạo 3-5 suất chiếu cho mỗi phim-phòng
                    FOR i IN 1..(3 + (RANDOM() * 3)::INTEGER) LOOP
                            -- Chọn khung giờ ngẫu nhiên
                            slot_index := (RANDOM() * (array_length(time_slots, 1) - 1))::INTEGER + 1;
                            time_slot := time_slots[slot_index];

                            -- Tính thời gian kết thúc
                            end_time := time_slot + (movie_record.thoi_luong || ' minutes')::INTERVAL;

                            -- Kiểm tra không vượt quá 23:59
                            IF end_time > '23:59:59'::TIME THEN
                                end_time := '23:59:59'::TIME;
                            END IF;

                            -- Kiểm tra không trùng lặp
                            IF NOT EXISTS (
                                SELECT 1 FROM suat_chieu
                                WHERE ngay_chieu = target_date
                                  AND id_phong_chieu = room_record.id_phong_chieu
                                  AND (
                                    (thoi_gian_bat_dau <= time_slot AND thoi_gian_ket_thuc > time_slot) OR
                                    (thoi_gian_bat_dau < end_time AND thoi_gian_ket_thuc >= end_time) OR
                                    (thoi_gian_bat_dau >= time_slot AND thoi_gian_ket_thuc <= end_time)
                                    )
                            ) THEN
                                -- Tạo suất chiếu
                                INSERT INTO suat_chieu (
                                    ten_suat_chieu,
                                    ngay_chieu,
                                    thoi_gian_bat_dau,
                                    thoi_gian_ket_thuc,
                                    trang_thai,
                                    id_phim,
                                    id_phong_chieu,
                                    so_ghe_con_trong,
                                    tong_so_ghe,
                                    ngay_tao,
                                    ngay_cap_nhat
                                ) VALUES (
                                             movie_record.ten_phim || ' - ' || room_record.ten_phong_chieu || ' - ' || time_slot,
                                             target_date,
                                             time_slot,
                                             end_time,
                                             'DANG_CHIEU',
                                             movie_record.id_phim,
                                             room_record.id_phong_chieu,
                                             (30 + (RANDOM() * 20))::INTEGER, -- 30-50 ghế trống
                                             (50 + (RANDOM() * 20))::INTEGER, -- 50-70 tổng ghế
                                             NOW(),
                                             NOW()
                                         );

                                created_count := created_count + 1;
                            END IF;
                        END LOOP;
                END LOOP;
        END LOOP;

    -- Trả về kết quả
    message := 'Da tao thanh cong ' || created_count || ' suat chieu cho ngay ' || target_date;
    created_count := created_count;
    date_created := target_date;

    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

-- 2. FUNCTION TỰ ĐỘNG TẠO SUẤT CHIẾU CHO NHIỀU NGÀY (FIXED)
CREATE OR REPLACE FUNCTION generate_showtimes_for_period(
    start_date DATE,
    end_date DATE,
    cinema_id INTEGER DEFAULT NULL
)
    RETURNS TABLE(
                     message TEXT,
                     total_created INTEGER,
                     days_processed INTEGER
                 ) AS $$
DECLARE
    current_day DATE;
    total_created INTEGER := 0;
    days_processed INTEGER := 0;
    result RECORD;
BEGIN
    current_day := start_date;

    WHILE current_day <= end_date LOOP
            -- Tạo suất chiếu cho ngày hiện tại
            FOR result IN SELECT * FROM generate_showtimes_for_date(current_day, cinema_id) LOOP
                    total_created := total_created + result.created_count;
                END LOOP;

            days_processed := days_processed + 1;
            current_day := current_day + INTERVAL '1 day';
        END LOOP;

    message := 'Da tao thanh cong ' || total_created || ' suat chieu cho ' || days_processed || ' ngay';
    total_created := total_created;
    days_processed := days_processed;

    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

-- 3. TEST FUNCTION
-- Tạo suất chiếu cho ngày 25/09/2025
