-- ========================================
-- Hệ thống: TẠO SUẤT CHIẾU CHO TẤT CẢ CÁC RẠP
-- ========================================

-- Tạo suất chiếu cho nhiều ngày và tất cả rạp
-- Bao gồm cả phim DANG_CHIEU và SAP_CHIEU

-- Tạo hệ thống lịch chiếu động (rolling schedule) 7 ngày
-- Luôn duy trì 7 ngày liên tiếp từ ngày hiện tại

-- 1. Function tạo lịch chiếu động 7 ngày
CREATE OR REPLACE FUNCTION maintain_rolling_schedule()
    RETURNS TABLE(
                     message TEXT,
                     total_created INTEGER,
                     days_processed INTEGER,
                     cinemas_processed INTEGER
                 ) AS $func$
DECLARE
    total_created INTEGER := 0;
    days_processed INTEGER := 0;
    cinemas_processed INTEGER := 0;
    current_date DATE := CURRENT_DATE;
    end_date DATE := current_date + INTERVAL '6 days';
    loop_date DATE;
    cinema_record RECORD;
    movie_record RECORD;
    room_record RECORD;
    time_slot TIME;
    time_slots TIME[] := ARRAY[
        '08:00:00'::TIME, '08:30:00'::TIME, '09:00:00'::TIME, '09:30:00'::TIME,
        '10:00:00'::TIME, '10:30:00'::TIME, '11:00:00'::TIME, '11:30:00'::TIME,
        '12:00:00'::TIME, '12:30:00'::TIME, '13:00:00'::TIME, '13:30:00'::TIME,
        '14:00:00'::TIME, '14:30:00'::TIME, '15:00:00'::TIME, '15:30:00'::TIME,
        '16:00:00'::TIME, '16:30:00'::TIME, '17:00:00'::TIME, '17:30:00'::TIME,
        '18:00:00'::TIME, '18:30:00'::TIME, '19:00:00'::TIME, '19:30:00'::TIME,
        '20:00:00'::TIME, '20:30:00'::TIME, '21:00:00'::TIME, '21:30:00'::TIME
        ];
    slot_index INTEGER;
    end_time TIME;
    i INTEGER;
    cinema_created INTEGER;
    day_created INTEGER;
BEGIN
    -- Xóa suất chiếu cũ (quá 7 ngày) - xử lý foreign key constraint
    -- Xóa theo thứ tự: lich_su_khuyen_mai -> ve_phim -> suat_chieu

    -- Xóa lịch sử khuyến mãi liên quan đến vé phim của suất chiếu cũ
    DELETE FROM lich_su_khuyen_mai
    WHERE id_ve_phim IN (
        SELECT vp.id_ve_phim
        FROM ve_phim vp
                 JOIN suat_chieu sc ON vp.id_suat_chieu = sc.id_suat_chieu
        WHERE sc.ngay_chieu < current_date
    );

    -- Xóa vé phim của suất chiếu cũ
    DELETE FROM ve_phim
    WHERE id_suat_chieu IN (
        SELECT id_suat_chieu
        FROM suat_chieu
        WHERE ngay_chieu < current_date
    );

    -- Xóa suất chiếu cũ (quá 7 ngày)
    DELETE FROM suat_chieu WHERE ngay_chieu < current_date;

    -- Xóa suất chiếu cũ (quá 7 ngày trong tương lai) - xử lý tương tự
    DELETE FROM lich_su_khuyen_mai
    WHERE id_ve_phim IN (
        SELECT vp.id_ve_phim
        FROM ve_phim vp
                 JOIN suat_chieu sc ON vp.id_suat_chieu = sc.id_suat_chieu
        WHERE sc.ngay_chieu > end_date
    );

    DELETE FROM ve_phim
    WHERE id_suat_chieu IN (
        SELECT id_suat_chieu
        FROM suat_chieu
        WHERE ngay_chieu > end_date
    );

    DELETE FROM suat_chieu WHERE ngay_chieu > end_date;

    -- Lặp qua từng ngày trong khoảng 7 ngày
    loop_date := current_date;
    WHILE loop_date <= end_date LOOP
            day_created := 0;

            -- Kiểm tra xem ngày này đã có suất chiếu chưa
            IF NOT EXISTS (
                SELECT 1 FROM suat_chieu
                WHERE ngay_chieu = loop_date
                LIMIT 1
            ) THEN
                -- Lấy danh sách tất cả rạp
                FOR cinema_record IN
                    SELECT id_rap_chieu, ten_rap_chieu
                    FROM rap_chieu
                    ORDER BY id_rap_chieu
                    LOOP
                        cinema_created := 0;

                        -- Lấy danh sách phim đang chiếu và sắp chiếu
                        FOR movie_record IN
                            SELECT id_phim, ten_phim, thoi_luong, trang_thai
                            FROM phim
                            WHERE trang_thai IN ('DANG_CHIEU', 'SAP_CHIEU')
                            ORDER BY RANDOM()
                            LOOP
                                -- Lấy danh sách phòng chiếu của rạp hiện tại
                                FOR room_record IN
                                    SELECT id_phong_chieu, ten_phong_chieu
                                    FROM phong_chieu
                                    WHERE id_rap_chieu = cinema_record.id_rap_chieu
                                    ORDER BY id_phong_chieu
                                    LOOP
                                        -- Tạo 2-4 suất chiếu cho mỗi phim-phòng
                                        FOR i IN 1..(2 + (RANDOM() * 3)::INTEGER) LOOP
                                                -- Chọn khung giờ ngẫu nhiên
                                                slot_index := (RANDOM() * (array_length(time_slots, 1) - 1))::INTEGER + 1;
                                                time_slot := time_slots[slot_index];

                                                -- Tính thời gian kết thúc
                                                end_time := time_slot + (movie_record.thoi_luong || ' minutes')::INTERVAL;

                                                -- Kiểm tra không vượt quá 23:59
                                                IF end_time > '23:59:59'::TIME THEN
                                                    CONTINUE;
                                                END IF;

                                                -- Kiểm tra thời gian kết thúc phải lớn hơn thời gian bắt đầu
                                                IF end_time <= time_slot THEN
                                                    CONTINUE;
                                                END IF;

                                                -- Kiểm tra không trùng lặp
                                                IF NOT EXISTS (
                                                    SELECT 1 FROM suat_chieu
                                                    WHERE ngay_chieu = loop_date
                                                      AND id_phong_chieu = room_record.id_phong_chieu
                                                      AND (
                                                        (thoi_gian_bat_dau <= time_slot AND thoi_gian_ket_thuc > time_slot) OR
                                                        (thoi_gian_bat_dau < end_time AND thoi_gian_ket_thuc >= end_time) OR
                                                        (thoi_gian_bat_dau >= time_slot AND thoi_gian_ket_thuc <= end_time)
                                                        )
                                                ) THEN
                                                    -- Tạo suất chiếu
                                                    INSERT INTO suat_chieu (
                                                        ten_suat_chieu,
                                                        ngay_chieu,
                                                        thoi_gian_bat_dau,
                                                        thoi_gian_ket_thuc,
                                                        trang_thai,
                                                        id_phim,
                                                        id_phong_chieu,
                                                        so_ghe_con_trong,
                                                        tong_so_ghe,
                                                        ngay_tao,
                                                        ngay_cap_nhat
                                                    ) VALUES (
                                                                 movie_record.ten_phim || ' - ' || room_record.ten_phong_chieu || ' - ' || time_slot,
                                                                 loop_date,
                                                                 time_slot,
                                                                 end_time,
                                                                 'DANG_CHIEU',
                                                                 movie_record.id_phim,
                                                                 room_record.id_phong_chieu,
                                                                 (30 + (RANDOM() * 20))::INTEGER,
                                                                 (50 + (RANDOM() * 20))::INTEGER,
                                                                 NOW(),
                                                                 NOW()
                                                             );

                                                    cinema_created := cinema_created + 1;
                                                    total_created := total_created + 1;
                                                    day_created := day_created + 1;
                                                END IF;
                                            END LOOP;
                                    END LOOP;
                            END LOOP;

                        -- Đếm số rạp đã xử lý
                        IF cinema_created > 0 THEN
                            cinemas_processed := cinemas_processed + 1;
                        END IF;
                    END LOOP;

                -- Đếm số ngày đã xử lý
                IF day_created > 0 THEN
                    days_processed := days_processed + 1;
                END IF;
            END IF;

            loop_date := loop_date + INTERVAL '1 day';
        END LOOP;

    -- Trả về kết quả
    message := 'Da duy tri lich chieu dong 7 ngay tu ' || current_date || ' den ' || end_date || '. Tao ' || total_created || ' suat chieu cho ' || days_processed || ' ngay va ' || cinemas_processed || ' rap';
    total_created := total_created;
    days_processed := days_processed;
    cinemas_processed := cinemas_processed;

    RETURN NEXT;
END;
$func$ LANGUAGE plpgsql;

-- 2. Function kiểm tra và cập nhật lịch hàng ngày
CREATE OR REPLACE FUNCTION check_and_update_schedule()
    RETURNS TEXT AS $func$
DECLARE
    current_date DATE := CURRENT_DATE;
    end_date DATE := current_date + INTERVAL '6 days';
    missing_days INTEGER;
    result_message TEXT;
BEGIN
    -- Kiểm tra số ngày thiếu suất chiếu
    SELECT COUNT(*) INTO missing_days
    FROM generate_series(current_date, end_date, '1 day'::INTERVAL) AS date_series
    WHERE NOT EXISTS (
        SELECT 1 FROM suat_chieu
        WHERE ngay_chieu = date_series::DATE
    );

    IF missing_days > 0 THEN
        -- Có ngày thiếu, cập nhật lịch
        PERFORM maintain_rolling_schedule();
        result_message := 'Da cap nhat lich chieu: ' || missing_days || ' ngay bi thieu suat chieu';
    ELSE
        result_message := 'Lich chieu da day du cho 7 ngay tu ' || current_date || ' den ' || end_date;
    END IF;

    RETURN result_message;
END;
$func$ LANGUAGE plpgsql;

