SELECT
    ngay_chieu,
    COUNT(*) as so_suat_chieu,
    COUNT(DISTINCT id_phim) as so_phim,
    COUNT(DISTINCT id_phong_chieu) as so_phong
FROM suat_chieu
WHERE ngay_chieu BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '6 days')
GROUP BY ngay_chieu
ORDER BY ngay_chieu;

